const QB=[
  {id:'g01',cat:'GAV',q:"Durée initiale d'une GAV de droit commun ?",opts:["12h","24h","48h","72h"],c:1,art:"Art. 63 al.1 CPP",diff:1,expl:"La GAV initiale est de <strong>24 heures</strong>. Elle peut être prolongée de 24h par autorisation écrite et motivée du PR."},
  {id:'g02',cat:'GAV',q:"En criminalité organisée, la GAV peut atteindre :",opts:["48h","72h","96h","144h"],c:2,art:"Art. 706-88 CPP",diff:2,expl:"En CO, la GAV peut atteindre <strong>96h</strong> (4×24h). Au-delà de 48h, c'est le JLD qui autorise."},
  {id:'g03',cat:'GAV',q:"La notification des droits en GAV doit intervenir :",opts:["Dans l'heure","Immédiatement","Dans les 3h","Avant la 1ère audition"],c:1,art:"Art. 63-1 CPP",diff:1,expl:"La notification doit être <strong>immédiate</strong> dès le placement. Tout retard constitue une formalité substantielle violée."},
  {id:'g04',cat:'GAV',q:"Depuis la loi du 22/04/2024, le délai de carence de l'avocat est :",opts:["Réduit à 1h","Supprimé — avocat sans délai","Maintenu à 2h","Porté à 30 min"],c:1,art:"Art. 63-3-1 CPP (loi 22/04/2024)",diff:2,expl:"La loi du 22 avril 2024 a <strong>supprimé le délai de carence de 2h</strong>. L'avocat intervient désormais sans délai dès le début de la GAV."},
  {id:'g05',cat:'GAV',q:"L'avis d'un proche lors d'un placement en GAV doit être donné :",opts:["Immédiatement","Dans les 3h","Dans les 6h","Avant la 1ère prolongation"],c:0,art:"Art. 63-2 CPP",diff:2,expl:"L'avis à un proche doit être donné <strong>immédiatement</strong>. Il peut être différé par le PR pour des raisons impérieuses d'enquête."},
  {id:'g06',cat:'GAV',q:"La GAV en terrorisme peut atteindre :",opts:["96h","120h","144h","168h"],c:2,art:"Art. 706-88-1 CPP",diff:2,expl:"En matière de terrorisme, la GAV peut atteindre <strong>144 heures</strong> (6×24h), avec autorisation successive du PR puis du JLD."},
  {id:'g07',cat:'GAV',q:"Le point de départ de la GAV est :",opts:["L'arrivée au commissariat","La notification des droits","L'heure d'appréhension de la personne","La première audition"],c:2,art:"Art. 63 I al.3 CPP",diff:2,expl:"Le délai de GAV part de <strong>l'heure d'appréhension</strong>. Le transport vers les locaux est donc inclus dans la durée."},
  {id:'g08',cat:'GAV',q:"Un mineur de 10 ans peut-il être placé en garde à vue ?",opts:["Oui, 12h maximum","Oui, 24h maximum","Non, jamais","Oui sur autorisation JLD"],c:2,art:"Art. L413-6 CJPM",diff:2,expl:"La GAV est <strong>interdite pour les moins de 13 ans</strong>. Une retenue judiciaire de 12h maximum (non renouvelable) peut être prononcée par l'OPJ."},
  {id:'f01',cat:'FLAGRANCE',q:"La durée initiale de l'enquête de flagrance est de :",opts:["24h","48h","8 jours","15 jours"],c:2,art:"Art. 53 al.1 CPP",diff:1,expl:"L'enquête de flagrance dure <strong>8 jours</strong>. Elle peut être prolongée de 8 jours supplémentaires par le JLD pour les crimes/délits ≥5 ans."},
  {id:'f02',cat:'FLAGRANCE',q:"En flagrance, les perquisitions peuvent avoir lieu :",opts:["Uniquement entre 6h et 21h","De jour comme de nuit","Seulement avec accord JLD","Uniquement après 8h"],c:1,art:"Art. 59 al.3 CPP",diff:2,expl:"En flagrance, les perquisitions peuvent être effectuées <strong>de jour comme de nuit</strong>, sans les restrictions horaires de la préliminaire."},
  {id:'f03',cat:'FLAGRANCE',q:"Est qualifié de flagrant le crime ou délit :",opts:["Commis depuis moins de 24h","Qui se commet actuellement ou vient de se commettre","Constaté par deux témoins","Dont l'auteur est connu"],c:1,art:"Art. 53 al.1 CPP",diff:1,expl:"Est flagrant le crime/délit <strong>qui se commet actuellement ou vient de se commettre</strong>. Les hypothèses de poursuite publique et d'indices apparents sont aussi visées."},
  {id:'p01',cat:'PERQUIZ',q:"En enquête préliminaire, la perquisition au domicile nécessite :",opts:["L'accord oral de l'intéressé","Le consentement écrit et exprès","L'autorisation du préfet","L'ordonnance du JI"],c:1,art:"Art. 76 CPP",diff:2,expl:"En préliminaire, la perquisition requiert le <strong>consentement écrit et exprès</strong> de l'intéressé. En cas de refus, il faut une autorisation du JLD."},
  {id:'p02',cat:'PERQUIZ',q:"Les perquisitions de droit commun sont autorisées entre :",opts:["7h et 20h","6h et 21h","8h et 22h","6h et 20h"],c:1,art:"Art. 59 CPP",diff:1,expl:"Les perquisitions ne peuvent avoir lieu qu'entre <strong>6h et 21h</strong>, sauf en flagrance ou avec autorisation spéciale."},
  {id:'p03',cat:'PERQUIZ',q:"En cas d'absence de l'occupant lors d'une perquisition, combien de témoins sont requis ?",opts:["1","2","3","Un huissier"],c:1,art:"Art. 57 al.3 CPP",diff:2,expl:"En cas d'absence ou de refus, <strong>2 témoins</strong> étrangers à la police et à l'affaire doivent assister aux opérations."},
  {id:'p04',cat:'PERQUIZ',q:"La perquisition dans un cabinet d'avocat nécessite obligatoirement :",opts:["L'accord de l'avocat","La présence du bâtonnier ou son délégué","L'autorisation du garde des Sceaux","L'accord du client"],c:1,art:"Art. 56-1 CPP",diff:2,expl:"La présence du <strong>bâtonnier ou de son délégué</strong> est obligatoire lors de toute perquisition dans un cabinet d'avocat."},
  {id:'a01',cat:'AUDLIB',q:"En audition libre, la personne soupçonnée peut :",opts:["Être retenue contre sa volonté","Quitter les lieux à tout moment","Être placée en GAV pendant l'audition","Refuser d'être entendue et partir sans notification"],c:1,art:"Art. 61-1 CPP",diff:1,expl:"La personne en audition libre peut <strong>quitter les lieux à tout moment</strong>. L'OPJ doit l'informer de ce droit dès le début."},
  {id:'a02',cat:'AUDLIB',q:"L'audition libre est prévue à :",opts:["Art. 61 CPP","Art. 61-1 CPP","Art. 62 CPP","Art. 63 CPP"],c:1,art:"Art. 61-1 CPP",diff:1,expl:"L'audition libre est définie à l'<strong>art. 61-1 CPP</strong>, issu de la loi du 27 mai 2014 (transposant la directive UE 2012/13)."},
  {id:'m01',cat:'MANDATS',q:"Le mandat d'amener permet de :",opts:["Incarcérer la personne","La conduire devant le JI ou le PR","La placer en GAV","La surveiller à distance"],c:1,art:"Art. 122 CPP",diff:2,expl:"Le mandat d'amener ordonne de <strong>conduire la personne devant le magistrat</strong> qui l'a décerné. Il ne permet pas l'incarcération."},
  {id:'m02',cat:'MANDATS',q:"Le mandat d'arrêt vise une personne :",opts:["Coopérative et présente","En fuite ou résidant à l'étranger","Mineure uniquement","Mise en examen pour délit"],c:1,art:"Art. 131 CPP",diff:2,expl:"Le mandat d'arrêt vise les personnes <strong>en fuite ou résidant à l'étranger</strong>. Il ordonne leur arrestation et incarcération provisoire."},
  {id:'o01',cat:'OPJ',q:"L'habilitation OPJ est accordée par :",opts:["Le préfet","Le garde des Sceaux","Le procureur général près la CA","Le PR"],c:2,art:"Art. 16 al.2 CPP",diff:2,expl:"L'habilitation OPJ est accordée par le <strong>procureur général</strong> près la cour d'appel du ressort dans lequel le fonctionnaire est affecté."},
  {id:'o02',cat:'OPJ',q:"La compétence d'un OPJ en commission rogatoire est :",opts:["Limitée à son ressort","Nationale automatiquement","Limitée à sa région","Limitée au ressort de la CA"],c:1,art:"Art. 18 al.4 CPP",diff:2,expl:"En CR, l'OPJ bénéficie d'une <strong>compétence nationale automatique</strong>, sans avoir besoin d'autorisation spéciale."},
  {id:'pr01',cat:'PRESCRIP',q:"Depuis la loi du 27 fév. 2017, la prescription d'un crime est de :",opts:["10 ans","15 ans","20 ans","30 ans"],c:2,art:"Art. 7 CPP",diff:1,expl:"Depuis la loi du 27 février 2017, la prescription des crimes est de <strong>20 ans</strong> (contre 10 ans auparavant)."},
  {id:'pr02',cat:'PRESCRIP',q:"Depuis la loi du 27 fév. 2017, la prescription d'un délit est de :",opts:["3 ans","5 ans","6 ans","10 ans"],c:2,art:"Art. 8 CPP",diff:1,expl:"La prescription des délits est désormais de <strong>6 ans</strong> (contre 3 ans avant 2017)."},
  {id:'pr03',cat:'PRESCRIP',q:"Les crimes contre l'humanité sont :",opts:["Prescrits par 30 ans","Prescrits par 50 ans","Prescrits par 100 ans","Imprescriptibles"],c:3,art:"Art. 213-5 CP",diff:1,expl:"Les crimes contre l'humanité sont <strong>imprescriptibles</strong> en droit français et international."},
  {id:'r01',cat:'RECIDIVE',q:"La récidive légale est une circonstance :",opts:["Atténuante","Aggravante réelle","Aggravante légale","Exonératoire"],c:2,art:"Art. 132-8 CP",diff:1,expl:"La récidive est une <strong>circonstance aggravante légale</strong> qui entraîne automatiquement un doublement des peines maximales."},
  {id:'r02',cat:'RECIDIVE',q:"La réitération d'infraction (art. 132-16-7 CP) exige :",opts:["Une condamnation définitive antérieure","Aucune condition de condamnation préalable","Un délai de moins de 5 ans","Deux infractions identiques"],c:1,art:"Art. 132-16-7 CP",diff:2,expl:"La réitération ne nécessite <strong>aucune condamnation définitive préalable</strong>. Elle diffère de la récidive légale sur ce point essentiel."},
  {id:'ld01',cat:'LEGDEF',q:"La légitime défense est définie à :",opts:["Art. 122-1 CP","Art. 122-4 CP","Art. 122-5 CP","Art. 122-7 CP"],c:2,art:"Art. 122-5 CP",diff:1,expl:"La légitime défense des personnes et des biens est prévue à l'<strong>art. 122-5 CP</strong>. Elle constitue un fait justificatif."},
  {id:'ld02',cat:'LEGDEF',q:"Les 3 conditions cumulatives de la légitime défense sont :",opts:["Nécessité + proportionnalité","Nécessité + simultanéité + proportionnalité","Proportionnalité + urgence","Automatique si agression illicite"],c:1,art:"Art. 122-5 CP",diff:2,expl:"La légitime défense exige 3 conditions cumulatives : <strong>nécessité + simultanéité + proportionnalité</strong>."},
  {id:'n01',cat:'NULLITES',q:"La nullité relative (art. 802 CPP) nécessite :",opts:["Uniquement une irrégularité formelle","La preuve d'un grief subi par la partie","Une violation d'ordre public","La mauvaise foi de l'OPJ"],c:1,art:"Art. 802 CPP",diff:2,expl:"La nullité relative exige la démonstration d'un <strong>grief concret</strong> pour la partie. Principe : pas de nullité sans grief."},
  {id:'i01',cat:'INSTRUCTION',q:"Le juge d'instruction est saisi par :",opts:["Plainte directe seule","Réquisitoire introductif du parquet","Signalement de l'OPJ","Arrêté préfectoral"],c:1,art:"Art. 80 CPP",diff:1,expl:"Le juge d'instruction est saisi par un <strong>réquisitoire introductif</strong> du parquet, ou par une plainte avec constitution de partie civile."},
  {id:'i02',cat:'INSTRUCTION',q:"La mise en examen intervient s'il existe :",opts:["Un simple soupçon","Des indices graves ou concordants","Une preuve directe","Un aveu"],c:1,art:"Art. 80-1 CPP",diff:2,expl:"La MEX requiert des <strong>indices graves ou concordants</strong> rendant vraisemblable la participation à l'infraction."},
  {id:'t01',cat:'TAJ',q:"Le TAJ est la fusion de :",opts:["FNAEG + FAED","STIC (PN) + JUDEX (GN)","FNAEG + SIS","FAED + FPR"],c:1,art:"Décret 2012-652",diff:2,expl:"Le TAJ (Traitement des Antécédents Judiciaires) est la fusion des anciens <strong>STIC (Police Nationale) et JUDEX (Gendarmerie Nationale)</strong>."},
  {id:'t02',cat:'TAJ',q:"Le FNAEG contient :",opts:["Les empreintes digitales","Les profils ADN","Les antécédents judiciaires","Les signalements internationaux"],c:1,art:"Art. 706-54 CPP",diff:2,expl:"Le FNAEG (Fichier National Automatisé des Empreintes Génétiques) contient les <strong>profils ADN</strong> des condamnés et mis en cause."},
  {id:'al01',cat:'ALTERNATIVES',q:"La composition pénale (art. 41-2 CPP) s'applique aux délits punis d'au maximum :",opts:["3 ans","5 ans","7 ans","Tout délit"],c:1,art:"Art. 41-2 CPP",diff:2,expl:"La composition pénale s'applique aux délits punis d'au maximum <strong>5 ans d'emprisonnement</strong>."},
  {id:'al02',cat:'ALTERNATIVES',q:"L'exécution de la composition pénale entraîne :",opts:["La mise en mouvement de l'AP","L'extinction de l'action publique","Un classement provisoire","Une mise en examen"],c:1,art:"Art. 41-2 CPP",diff:2,expl:"L'exécution de la composition pénale entraîne <strong>l'extinction de l'action publique</strong>. En cas de refus, les poursuites reprennent."},
  {id:'in01',cat:'INFRACTIONS',q:"Le vol simple (art. 311-1 CP) est puni de :",opts:["1 an / 15k€","3 ans / 45k€","5 ans / 75k€","Contravention"],c:1,art:"Art. 311-1 CP",diff:1,expl:"Le vol simple est puni de <strong>3 ans d'emprisonnement et 45 000 € d'amende</strong>."},
  {id:'in02',cat:'INFRACTIONS',q:"L'escroquerie (art. 313-1 CP) suppose :",opts:["Une soustraction","Une tromperie par manœuvres → remise","Un détournement","Une violence"],c:1,art:"Art. 313-1 CP",diff:2,expl:"L'escroquerie exige <strong>une tromperie (faux nom, manœuvres frauduleuses) suivie d'une remise</strong> par la victime."},
  {id:'in03',cat:'INFRACTIONS',q:"Le vol en bande organisée (art. 311-9 CP) est :",opts:["Un délit puni de 10 ans","Un crime puni de 15 ans RC","Un délit puni de 7 ans","Un crime puni de 20 ans RC"],c:1,art:"Art. 311-9 CP",diff:2,expl:"Le vol en bande organisée est un <strong>crime puni de 15 ans de réclusion criminelle</strong>. Piège classique : beaucoup pensent que c'est un délit !"},
  {id:'in04',cat:'INFRACTIONS',q:"Le meurtre (art. 221-1 CP) se distingue des violences mortelles (art. 222-7 CP) par :",opts:["Le mode opératoire","L'intention de tuer (animus necandi)","La qualité de la victime","Le lieu de commission"],c:1,art:"Art. 221-1 vs 222-7 CP",diff:2,expl:"Le meurtre exige l'<strong>intention de tuer</strong> (animus necandi). Les violences mortelles n'impliquent que l'intention de blesser."},
  {id:'in05',cat:'INFRACTIONS',q:"La conduite avec un taux d'alcool ≥ 0,80 g/l est :",opts:["Une contravention","Un délit puni de 2 ans + 4500€","Un crime","Non punissable"],c:1,art:"Art. L234-1 C.route",diff:1,expl:"La conduite avec un taux ≥ 0,80 g/l est un <strong>délit puni de 2 ans + 4 500 €</strong>. Le taux contravention est 0,50-0,80 g/l."},
  {id:'in06',cat:'INFRACTIONS',q:"Les stupéfiants : le seuil délictuel est :",opts:["0,5 mg/l","1 g/l","Il n'y a pas de seuil — toute présence est délictuelle","0,80 g/l"],c:2,art:"Art. L235-1 C.route",diff:2,expl:"Pour les stupéfiants, <strong>il n'y a aucun seuil</strong>. Toute présence dans l'organisme constitue le délit de conduite sous l'influence de stupéfiants."},
  {id:'in07',cat:'INFRACTIONS',q:"L'abus de confiance (art. 314-1 CP) suppose :",opts:["Une soustraction directe","Une remise préalable licite puis un détournement","Une tromperie initiale","Des violences"],c:1,art:"Art. 314-1 CP",diff:2,expl:"L'ADB exige une <strong>remise préalable et licite</strong> du bien (mandat, dépôt, prêt), suivie d'un détournement."},
  {id:'in08',cat:'INFRACTIONS',q:"Le recel (art. 321-1 CP) est une infraction :",opts:["Instantanée","Continue et autonome","Formelle","D'habitude"],c:1,art:"Art. 321-1 CP",diff:2,expl:"Le recel est une infraction <strong>continue et autonome</strong>. Elle persiste tant que l'objet est détenu."},
  {id:'in09',cat:'INFRACTIONS',q:"L'usage illicite de stupéfiants (art. L3421-1 CSP) est puni de :",opts:["6 mois + 7500€","1 an + 3750€","2 ans + 4500€","Contravention"],c:1,art:"Art. L3421-1 CSP",diff:1,expl:"L'usage de stupéfiants est puni de <strong>1 an + 3 750 €</strong>. L'amende forfaitaire délictuelle (AFD) de 200 € est possible."},
  {id:'in10',cat:'INFRACTIONS',q:"La tentative est TOUJOURS punissable pour :",opts:["Les contraventions","Les délits si le texte le prévoit","Les crimes","Les délits uniquement"],c:2,art:"Art. 121-5 CP",diff:1,expl:"Aux termes de l'<strong>art. 121-5 CP</strong>, la tentative est <strong>toujours punissable pour les crimes</strong>. Pour les délits, un texte exprès est requis. Jamais pour les contraventions."},
  {id:'in11',cat:'INFRACTIONS',q:"L'outrage à personne dépositaire de l'autorité publique (art. 433-5 CP) est :",opts:["Physique","Verbal et directement adressé (non public)","Public uniquement","Identique à la rébellion"],c:1,art:"Art. 433-5 CP",diff:2,expl:"L'outrage est une expression <strong>outrageante NON PUBLIQUE directement adressée</strong> à la personne. Si public = injure (loi 1881)."},
  {id:'in12',cat:'INFRACTIONS',q:"La rébellion (art. 433-6 CP) suppose :",opts:["Des insultes envers un agent","Une résistance violente et active à l'égard d'une PDAP","Un simple refus d'obtempérer","Une résistance passive"],c:1,art:"Art. 433-6 CP",diff:2,expl:"La rébellion exige une <strong>résistance VIOLENTE et ACTIVE</strong>. La résistance passive (se laisser tomber) n'est PAS une rébellion."},
  {id:'lp01',cat:'LIBERTES',q:"L'article 66 de la Constitution fait de l'autorité judiciaire :",opts:["Gardienne de l'ordre public","Gardienne de la liberté individuelle","Gardienne de la sécurité nationale","Gardienne de la propriété"],c:1,art:"Art. 66 Constitution",diff:1,expl:"L'art. 66 dispose que <strong>'l'autorité judiciaire est gardienne de la liberté individuelle'</strong>. C'est le fondement constitutionnel de la GAV et de la DP."},
  {id:'lp02',cat:'LIBERTES',q:"L'article 3 CEDH (interdiction de la torture) est :",opts:["Relatif — peut être limité par loi","Qualifié — peut être limité en urgence","Absolu — aucune dérogation possible","Limité aux États membres du Conseil de l'Europe"],c:2,art:"Art. 3 CEDH",diff:2,expl:"L'art. 3 CEDH est un <strong>droit ABSOLU</strong>. Aucune circonstance, même le terrorisme ou l'état de guerre, ne peut justifier une dérogation."},
  {id:'lp03',cat:'LIBERTES',q:"La présomption d'innocence est renversée uniquement par :",opts:["La mise en examen","La garde à vue","Une condamnation définitive","Le renvoi en jugement"],c:2,art:"Art. 9 DDHC",diff:1,expl:"La présomption d'innocence est renversée <strong>uniquement par une condamnation définitive</strong>. La MEX, la GAV et le renvoi ne la suppriment pas."},
  {id:'co01',cat:'CDO',q:"Les écoutes téléphoniques en instruction sont autorisées par :",opts:["Le procureur de la République","Le juge d'instruction","Le JLD","L'OPJ avec accord PR"],c:1,art:"Art. 100 CPP",diff:2,expl:"En instruction, les écoutes téléphoniques sont ordonnées par le <strong>juge d'instruction</strong>. En préliminaire, c'est le JLD (sur réq. PR, art. 706-95)."},
  {id:'co02',cat:'CDO',q:"La géolocalisation en temps réel au-delà de 15 jours nécessite :",opts:["Simple autorisation du PR","Autorisation du JLD","Ordonnance du JI","Accord du préfet"],c:1,art:"Art. 230-32 CPP",diff:2,expl:"La géolocalisation peut être autorisée par le PR pour 15 jours. Au-delà, <strong>le JLD est obligatoire</strong> (1 mois renouvelable)."},
  {id:'co03',cat:'CDO',q:"L'association de malfaiteurs criminelle (art. 450-1 CP) est punie de :",opts:["5 ans + 75k€","7 ans + 100k€","10 ans + 150k€","15 ans RC"],c:2,art:"Art. 450-1 CP",diff:2,expl:"L'AM criminelle est punie de <strong>10 ans d'emprisonnement et 150 000 €</strong> d'amende."},
  {id:'min01',cat:'MINEURS',q:"Depuis le CJPM 2021, la présomption irréfragable d'irresponsabilité s'applique aux moins de :",opts:["10 ans","12 ans","13 ans","16 ans"],c:2,art:"Art. L11-1 CJPM",diff:2,expl:"Le CJPM (entré en vigueur le 30/09/2021) fixe à <strong>13 ans</strong> l'âge de la présomption irréfragable d'irresponsabilité pénale."},
  {id:'min02',cat:'MINEURS',q:"Pour un mineur de 13 à 16 ans, la GAV est possible pour :",opts:["Tout délit","Toute infraction punie d'emprisonnement","Infractions punies d'au moins 5 ans","Infractions punies d'au moins 3 ans"],c:2,art:"Art. L413-6 CJPM",diff:2,expl:"Pour les 13-16 ans, la GAV est possible uniquement si l'infraction est punie d'<strong>au moins 5 ans d'emprisonnement</strong>."},
  {id:'cr01',cat:'COMMISSION',q:"Une commission rogatoire peut être délivrée par :",opts:["Le procureur de la République","Le juge d'instruction exclusivement","L'OPJ sur autorisation PR","Le JLD"],c:1,art:"Art. 151 CPP",diff:1,expl:"La CR est délivrée <strong>exclusivement par le juge d'instruction</strong>. Le PR ne peut pas en délivrer."},
  {id:'cr02',cat:'COMMISSION',q:"En commission rogatoire, l'OPJ ne peut PAS :",opts:["Procéder à des perquisitions","Placer en garde à vue","Délivrer des mandats","Auditionner des témoins"],c:2,art:"Art. 152 CPP",diff:2,expl:"En CR, l'OPJ ne peut pas <strong>délivrer des mandats</strong> — cela reste la prérogative exclusive du juge d'instruction."},
  {id:'ap01',cat:'ACTION_PUB',q:"Le classement sans suite par le procureur :",opts:["Éteint définitivement l'action publique","N'éteint PAS l'AP — réversible","Équivaut à un non-lieu","Transfère l'AP à la partie civile"],c:1,art:"Art. 40-1 CPP",diff:2,expl:"Le classement sans suite <strong>ne constitue pas une décision définitive</strong>. Le PR peut revenir sur sa décision en cas d'éléments nouveaux."},
  {id:'ap02',cat:'ACTION_PUB',q:"Les missions de la Police Judiciaire selon l'art. 14 CPP sont :",opts:["Surveiller, interpeller, juger","Constater, rassembler les preuves, rechercher les auteurs","Prévenir, dissuader, sanctionner","Enquêter, poursuivre, condamner"],c:1,art:"Art. 14 CPP",diff:1,expl:"L'art. 14 CPP définit 3 missions PJ : <strong>constater les infractions, rassembler les preuves, rechercher les auteurs</strong>."},
  /* === NOUVEAUX QCM v25 === */
  /* CONTRÔLES */
  {id:'ci01',cat:'CONTROLES',q:"Le contrôle d'identité peut durer au maximum :",opts:["1 heure","2 heures","4 heures","Sans limite précise"],c:2,art:"Art. 78-3 CPP",diff:2,expl:"La rétention aux fins de vérification d'identité est limitée à <strong>4 heures maximum</strong>. Passé ce délai, la personne doit être libérée ou placée en GAV."},
  {id:'ci02',cat:'CONTROLES',q:"Lors d'une vérification d'identité (art. 78-3), l'avis au PR doit être donné :",opts:["Dans l'heure","Dans les 3 heures","Immédiatement","Avant la 1ère vérification"],c:2,art:"Art. 78-3 CPP",diff:2,expl:"L'avis au Procureur de la République doit être donné <strong>immédiatement</strong> dès le début de la rétention aux fins de vérification."},
  {id:'ci03',cat:'CONTROLES',q:"Le contrôle d'identité basé sur l'apparence ethnique est :",opts:["Autorisé en zone frontalière","Autorisé avec réquisitions PR","Interdit — faute lourde de l'État","Autorisé sur décision OPJ"],c:2,art:"Art. 78-2 CPP — Cass. 2016",diff:2,expl:"La Cour de cassation (9 nov. 2016) a consacré l'<strong>interdiction absolue du profilage ethnique</strong>. Un contrôle fondé sur l'apparence constitue une faute lourde de l'État."},
  {id:'ci04',cat:'CONTROLES',q:"La fouille de véhicule sur réquisitions du PR est régie par :",opts:["Art. 56 CPP","Art. 78-2-2 CPP","Art. 76 CPP","Art. 53 CPP"],c:1,art:"Art. 78-2-2 CPP",diff:2,expl:"La fouille de véhicule sur réquisitions du PR est prévue à l'<strong>art. 78-2-2 CPP</strong>. Elle nécessite des réquisitions écrites définissant un périmètre et une durée."},
  {id:'ci05',cat:'CONTROLES',q:"Un étranger en situation irrégulière peut être retenu en CRA pendant :",opts:["24h maximum","48h puis JLD","7 jours maximum","90 jours maximum"],c:3,art:"CESEDA — Art. L742-1",diff:3,expl:"La durée maximale de rétention administrative est de <strong>90 jours</strong> : 48h préfet + 28j JLD + renouvellements successifs jusqu'au plafond."},
  /* MANDATS */
  {id:'mand01',cat:'MANDATS',q:"Le mandat d'amener permet de :",opts:["Placer la personne en GAV immédiatement","Incarcérer la personne provisoirement","La conduire de force devant le juge qui l'a décerné","Surveiller la personne à distance"],c:2,art:"Art. 122 al.2 CPP",diff:2,expl:"Le mandat d'amener ordonne de <strong>conduire physiquement la personne devant le magistrat</strong>. Il n'emporte pas d'incarcération — c'est le mandat de dépôt."},
  {id:'mand02',cat:'MANDATS',q:"Le mandat de recherche est émis par :",opts:["Le Juge d'Instruction","Le Juge des Libertés et de la Détention","Le Procureur de la République","L'OPJ habilité"],c:2,art:"Art. 122-4 CPP",diff:2,expl:"Le mandat de recherche est émis par le <strong>Procureur de la République</strong> (et non par le JI). Il concerne les infractions punies d'au moins 3 ans."},
  {id:'mand03',cat:'MANDATS',q:"Le mandat d'arrêt vise une personne :",opts:["Présente et coopérative","En fuite ou résidant à l'étranger","Mineure uniquement","Placée en contrôle judiciaire"],c:1,art:"Art. 131 CPP",diff:1,expl:"Le mandat d'arrêt est spécifiquement conçu pour les personnes <strong>en fuite ou résidant à l'étranger</strong>. Il ordonne leur arrestation et incarcération provisoire."},
  {id:'mand04',cat:'MANDATS',q:"Quelle est la durée de validité d'un mandat de recherche ?",opts:["6 mois","1 an renouvelable","Sans limite","3 ans"],c:1,art:"Art. 122-4 CPP",diff:3,expl:"Le mandat de recherche a une durée de <strong>1 an renouvelable</strong>. À l'expiration, il doit être renouvelé par le PR pour rester exécutoire."},
  {id:'mand05',cat:'MANDATS',q:"Lors de l'exécution d'un mandat, l'OPJ doit :",opts:["Garder le mandat secret","Exhiber le mandat et notifier les droits","Attendre l'accord du JI","Notifier uniquement si demandé"],c:1,art:"Art. 122 CPP",diff:1,expl:"L'OPJ exécutant un mandat doit <strong>exhiber le mandat et notifier ses droits</strong> à la personne visée, notamment le droit à un avocat."},
  /* MESURES COERCITIVES */
  {id:'mc01',cat:'MESURES_COERC',q:"L'ARSE nécessite une peine minimale encourrue de :",opts:["6 mois","1 an","2 ans","3 ans"],c:2,art:"Art. 142-5 CPP",diff:2,expl:"L'assignation à résidence avec surveillance électronique requiert que la personne encourt une peine d'au moins <strong>2 ans d'emprisonnement</strong>."},
  {id:'mc02',cat:'MESURES_COERC',q:"La détention provisoire en matière correctionnelle (délit ≤10 ans) dure au maximum :",opts:["4 mois non renouvelables","1 an","2 ans","4 mois renouvelables jusqu'à 2 ans"],c:3,art:"Art. 145-1 CPP",diff:3,expl:"En matière correctionnelle (délit ≤10 ans), la DP peut durer <strong>4 mois renouvelables dans la limite de 2 ans maximum</strong> total."},
  {id:'mc03',cat:'MESURES_COERC',q:"Les obligations du contrôle judiciaire (art. 138 CPP) sont :",opts:["Indicatives — le juge peut en créer de nouvelles","Limitatives — liste fermée de 17 obligations","Facultatives — à la discrétion du prévenu","Identiques à l'ARSE"],c:1,art:"Art. 138 CPP",diff:2,expl:"Les obligations du contrôle judiciaire constituent une <strong>liste LIMITATIVE</strong> de 17 obligations. Le juge ne peut en inventer aucune autre."},
  {id:'mc04',cat:'MESURES_COERC',q:"La détention provisoire est décidée par :",opts:["Le Juge d'Instruction seul","Le Procureur de la République","Le Juge des Libertés et de la Détention","Le Président du Tribunal"],c:2,art:"Art. 143-1 CPP",diff:1,expl:"La détention provisoire est ordonnée par le <strong>JLD</strong>, saisi par ordonnance du JI. Le JI seul ne peut jamais décider de la DP."},
  {id:'mc05',cat:'MESURES_COERC',q:"La DP peut être ordonnée dès lors que l'infraction est punie d'au moins :",opts:["1 an","2 ans","3 ans","5 ans"],c:2,art:"Art. 143-1 CPP",diff:2,expl:"La détention provisoire nécessite que la personne soit mise en examen pour un délit puni d'au moins <strong>3 ans d'emprisonnement</strong> ou tout crime."},
  /* FICHIERS */
  {id:'fij01',cat:'FICHIERS',q:"L'inscription au FIJAISV est obligatoire pour :",opts:["Tout crime","Les infractions sexuelles sur mineurs et les agressions sexuelles","Tous les délits violents","Les crimes en bande organisée"],c:1,art:"Art. 706-53-1 CPP",diff:2,expl:"L'inscription au FIJAISV est obligatoire pour les <strong>infractions sexuelles sur mineurs et les agressions sexuelles</strong> graves. La durée est de 30 ans pour les crimes, 20 ans pour les délits."},
  {id:'fij02',cat:'FICHIERS',q:"Les obligations déclaratives au FIJAISV sont :",opts:["Mensuelles uniquement","Mensuelles + semestrielles + annuelles selon l'infraction","Annuelles uniquement","Trimestrielles"],c:1,art:"Art. 706-53-5 CPP",diff:3,expl:"Les obligations au FIJAISV varient selon la gravité : <strong>mensuelles (déplacements), semestrielles (adresse) ou annuelles</strong> selon la nature de l'infraction."},
  {id:'fij03',cat:'FICHIERS',q:"Le FNAEG contient :",opts:["Les empreintes digitales","Les antécédents judiciaires","Les profils ADN des mis en cause et condamnés","Les titres de séjour des étrangers"],c:2,art:"Art. 706-54 CPP",diff:1,expl:"Le FNAEG (Fichier National Automatisé des Empreintes Génétiques) contient exclusivement les <strong>profils ADN</strong> des personnes condamnées et mises en cause."},
  {id:'fij04',cat:'FICHIERS',q:"Le SALVAC est géré par :",opts:["La DGSI","L'OCRVP","Europol","La DCPJ"],c:1,art:"Décret SALVAC",diff:3,expl:"SALVAC (Système d'Analyse des Liens de la Violence Associée aux Crimes) est géré par l'<strong>OCRVP</strong> (Office Central pour la Répression des Violences aux Personnes)."},
  {id:'fij05',cat:'FICHIERS',q:"Le TAJ est la fusion de :",opts:["FNAEG + FAED","STIC (PN) + JUDEX (GN)","FIJAISV + FAED","FPR + TAJ"],c:1,art:"Décret 2012-652",diff:2,expl:"Le TAJ (Traitement des Antécédents Judiciaires) est né de la fusion du <strong>STIC (Police Nationale) et du JUDEX (Gendarmerie Nationale)</strong>."},
  /* ALERTE ENLÈVEMENT & ART. 74 */
  {id:'ae01',cat:'ENQUETES_SPEC',q:"Le plan Alerte Enlèvement nécessite combien de critères cumulatifs ?",opts:["3","4","5","6"],c:2,art:"Décret 2006 — Alerte enlèvement",diff:2,expl:"Le déclenchement de l'Alerte Enlèvement requiert la réunion de <strong>5 critères cumulatifs</strong> : victime mineure, enlèvement avéré, intégrité menacée, description suspect/véhicule, et compétence judiciaire."},
  {id:'ae02',cat:'ENQUETES_SPEC',q:"La mort suspecte (art. 74 CPP) nécessite :",opts:["Une qualification pénale immédiate","La réquisition d'un médecin légiste obligatoirement","L'ouverture d'une information judiciaire d'office","Un accord préalable du JI"],c:1,art:"Art. 74 CPP",diff:2,expl:"Lors d'une mort de cause inconnue, <strong>la réquisition d'un médecin légiste est obligatoire</strong>. L'OPJ n'a pas besoin d'une qualification pénale préalable pour agir."},
  {id:'ae03',cat:'ENQUETES_SPEC',q:"Les disparitions inquiétantes (art. 74-1 CPP) impliquent :",opts:["Une GAV immédiate","L'ouverture d'une information judiciaire automatique","3 critères : disparition, inquiétude, faits criminels probables","Seulement l'alerte aux médias"],c:2,art:"Art. 74-1 CPP",diff:3,expl:"L'art. 74-1 CPP exige <strong>3 critères</strong> : la disparition effective, un caractère inquiétant, et des éléments rendant probables une atteinte criminelle."},
  /* ACTION PUBLIQUE */
  {id:'apub01',cat:'ACTION_PUB',q:"La composition pénale est possible pour les délits punis d'au maximum :",opts:["3 ans","5 ans","7 ans","Tous délits confondus"],c:1,art:"Art. 41-2 CPP",diff:2,expl:"La composition pénale (PR propose des mesures) est limitée aux délits punis d'au maximum <strong>5 ans d'emprisonnement</strong>."},
  {id:'apub02',cat:'ACTION_PUB',q:"L'exécution d'une composition pénale entraîne :",opts:["Une condamnation inscrite au casier B1","L'extinction de l'action publique","Un classement provisoire","Une mise en examen"],c:1,art:"Art. 41-2 CPP",diff:2,expl:"L'exécution réussie de la composition pénale entraîne <strong>l'extinction de l'action publique</strong>. La mesure n'est pas inscrite au casier judiciaire B1."},
  {id:'apub03',cat:'ACTION_PUB',q:"Parmi les causes d'extinction de l'action publique, on trouve :",opts:["Le retrait de plainte de la victime","La décision de classement sans suite","Le décès du prévenu","La constitution de partie civile"],c:2,art:"Art. 6 CPP",diff:2,expl:"Le <strong>décès du prévenu</strong> éteint l'action publique (art. 6 CPP). L'amnistie, la prescription, la chose jugée et l'abrogation de la loi l'éteignent aussi."},
  {id:'apub04',cat:'ACTION_PUB',q:"L'action publique et l'action civile diffèrent en ce que :",opts:["L'action publique cherche la réparation, l'action civile la punition","L'action publique cherche la sanction sociale, l'action civile la réparation du dommage","Elles ont les mêmes finalités","L'action publique ne peut être exercée que par la victime"],c:1,art:"Art. 1-2 CPP",diff:1,expl:"<strong>L'action publique vise à sanctionner l'infraction</strong> (finalité sociale). <strong>L'action civile vise à réparer le dommage</strong> subi par la victime."},
  /* LIBERTÉS PUBLIQUES */
  {id:'lib01',cat:'LIBERTES',q:"La vidéo-protection en voie publique nécessite :",opts:["Une autorisation du PR","Une autorisation préfectorale","Un avis du maire uniquement","Aucune autorisation particulière"],c:1,art:"Art. L251-2 CSI",diff:2,expl:"L'installation de caméras de vidéo-protection en voie publique nécessite une <strong>autorisation préfectorale</strong> (préalable, motivée, durée limitée)."},
  {id:'lib02',cat:'LIBERTES',q:"La durée maximale de conservation des images de vidéo-protection est de :",opts:["7 jours","15 jours","30 jours","90 jours"],c:2,art:"Art. L252-3 CSI",diff:2,expl:"Les images de vidéo-protection doivent être conservées au maximum <strong>30 jours</strong>. Au-delà, elles doivent être effacées sauf si elles sont utiles à une enquête."},
  {id:'lib03',cat:'LIBERTES',q:"En France, les armes sont classées en :",opts:["2 catégories (A et B)","3 catégories (A, B, C)","4 catégories (A, B, C, D)","5 catégories"],c:2,art:"Art. R311-2 CSI",diff:2,expl:"Depuis la réforme de 2013, les armes sont classées en <strong>4 catégories : A (prohibées), B (soumises à autorisation), C (soumises à déclaration), D (libre acquisition).</strong>"},
  {id:'lib04',cat:'LIBERTES',q:"L'usage des armes par la police (art. L435-1 CSI) nécessite :",opts:["Une autorisation du PR","2 conditions cumulatives","3 conditions cumulatives","Aucune condition particulière"],c:2,art:"Art. L435-1 CSI",diff:2,expl:"L'art. L435-1 CSI encadre l'usage des armes selon <strong>3 conditions cumulatives</strong> : absolue nécessité, proportionnalité, et une des 5 situations légales."},
  {id:'lib05',cat:'LIBERTES',q:"Une manifestation publique doit être déclarée :",opts:["24h à l'avance","3 jours à l'avance","15 jours à l'avance","Immédiatement avant"],c:1,art:"Art. L211-1 CSI",diff:2,expl:"Toute manifestation sur la voie publique doit faire l'objet d'une déclaration préalable <strong>3 jours à l'avance</strong> (entre 3 et 15 jours) auprès de la préfecture ou mairie."},
  /* PATRIMONIAL */
  {id:'pat01',cat:'PATRIMONIAL',q:"Le blanchiment simple (art. 324-1 CP) est puni de :",opts:["3 ans / 75k€","5 ans / 375k€","7 ans / 500k€","10 ans / 750k€"],c:1,art:"Art. 324-1 CP",diff:2,expl:"Le blanchiment est puni de <strong>5 ans d'emprisonnement et 375 000 €</strong> d'amende. Aggravé en bande organisée : 10 ans + 750 000 €."},
  {id:'pat02',cat:'PATRIMONIAL',q:"La confiscation de l'ensemble du patrimoine (art. 131-21 al. 9 CP) est :",opts:["Automatique pour tout crime","Une mesure exceptionnelle réservée aux infractions les plus graves","Applicable à tous les délits","Décidée par l'OPJ"],c:1,art:"Art. 131-21 al. 9 CP",diff:3,expl:"La confiscation totale du patrimoine est une <strong>mesure exceptionnelle</strong> réservée aux infractions les plus graves (terrorisme, trafic, criminalité organisée grave)."},
  {id:'pat03',cat:'PATRIMONIAL',q:"FICOBA est un fichier permettant de connaître :",opts:["Les condamnations pénales","Les comptes bancaires d'une personne","Le patrimoine immobilier","Les véhicules immatriculés"],c:1,art:"Décret FICOBA",diff:2,expl:"FICOBA (Fichier des Comptes Bancaires) répertorie l'ensemble des <strong>comptes bancaires</strong> ouverts en France. L'OPJ peut y accéder sur réquisition."},
  /* ENQUÊTES SPÉCIALES */
  {id:'es01',cat:'ENQUETES_SPEC',q:"En matière d'accident de la route, le dépistage de l'alcoolémie est :",opts:["Toujours facultatif","Obligatoire pour tout accident avec dommage corporel","Obligatoire uniquement sur décision du PR","Réservé aux accidents mortels"],c:1,art:"Art. L234-3 Code route",diff:2,expl:"Le dépistage de l'alcoolémie est <strong>obligatoire pour tout accident corporel</strong>. Il est facultatif en cas d'accident matériel uniquement."},
  {id:'es02',cat:'ENQUETES_SPEC',q:"La personne grièvement blessée (art. 74 al. 6 CPP) donne à l'OPJ :",opts:["Les pouvoirs de la flagrance uniquement","Des pouvoirs d'investigation propres avant qualification","Aucun pouvoir particulier","Les pouvoirs de la commission rogatoire"],c:1,art:"Art. 74 al. 6 CPP",diff:3,expl:"L'art. 74 al. 6 CPP confère à l'OPJ des <strong>pouvoirs d'investigation propres</strong> en cas de personne grièvement blessée, avant toute qualification pénale."},
  {id:'es03',cat:'ENQUETES_SPEC',q:"Lors d'une enquête accident avec dépistage de stupéfiants, les réquisitions médecin ITT sont :",opts:["Facultatives dans tous les cas","Obligatoires si blessé grave","Facultatives — à discrétion de l'OPJ","Uniquement sur autorisation PR"],c:1,art:"Art. 60-1 CPP — Art. R234-1 C.route",diff:2,expl:"Les réquisitions d'un médecin pour constater les lésions et l'ITT sont <strong>obligatoires en cas de blessé grave</strong>. Elles permettent de qualifier l'infraction avec précision."},
  /* DROIT PÉNAL GÉNÉRAL AVANCÉ */
  {id:'dpg01',cat:'INFRACTIONS',q:"Le concours réel d'infractions (art. 132-2 CP) existe quand :",opts:["Les infractions sont connexes","Plusieurs infractions distinctes sans condamnation définitive entre elles","Deux personnes commettent la même infraction","Une infraction est tentée sans aboutir"],c:1,art:"Art. 132-2 CP",diff:3,expl:"Le concours réel existe quand une même personne commet <strong>plusieurs infractions distinctes sans qu'une condamnation définitive ait été rendue</strong> entre elles."},
  {id:'dpg02',cat:'NULLITES',q:"La nullité textuelle (art. 171 CPP) :",opts:["Nécessite la preuve d'un grief concret","Est automatique dès la violation d'un texte l'édictant","Peut être régularisée après coup","N'entraîne pas la nullité de la procédure"],c:1,art:"Art. 171 CPP",diff:2,expl:"La nullité textuelle est <strong>automatique</strong> dès lors qu'un texte de loi l'édicte expressément — sans avoir à démontrer un grief particulier."},
  {id:'dpg03',cat:'INFRACTIONS',q:"En matière de concours réel, la règle principale est :",opts:["Le cumul illimité des peines","Non-cumul des peines d'emprisonnement (confusion)","L'absorption de la peine la plus faible","Le doublement automatique"],c:1,art:"Art. 132-3 et s. CP",diff:3,expl:"En matière de concours réel, c'est le principe de <strong>non-cumul (confusion) des peines d'emprisonnement</strong> qui s'applique : seule la peine la plus sévère est prononcée."},
  /* INSTRUCTION AVANCÉE */
  {id:'instr01',cat:'INSTRUCTION',q:"La Chambre de l'Instruction est saisie par :",opts:["Le Procureur uniquement","Appel de toute ordonnance du JI dans les 10 jours","Le JLD directement","La police judiciaire"],c:1,art:"Art. 185 CPP",diff:2,expl:"La Chambre de l'Instruction est saisie par <strong>appel dans les 10 jours</strong> de toute ordonnance du Juge d'Instruction, par le mis en examen, le PR, la partie civile."},
  {id:'instr02',cat:'INSTRUCTION',q:"La Cour d'Assises spéciale (sans jury populaire) est compétente pour :",opts:["Tous les crimes","Les crimes commis par des mineurs","Les crimes terroristes et en matière de trafic de stupéfiants aggravé","Les crimes en bande organisée simple"],c:2,art:"Art. 698-6 CPP",diff:3,expl:"La Cour d'Assises spéciale (composée uniquement de magistrats professionnels, sans jury) est compétente pour les <strong>affaires de terrorisme et certains crimes liés aux stupéfiants</strong>."},
  {id:'instr03',cat:'INSTRUCTION',q:"La Cour criminelle départementale (depuis 2023) juge :",opts:["Les crimes punis de perpétuité","Les crimes punis de 15 à 20 ans RC sans récidive","Tous les crimes sans jury","Les crimes organisés"],c:1,art:"Art. 380-16 CPP",diff:3,expl:"La Cour criminelle départementale, généralisée en 2023, juge les crimes <strong>punis de 15 à 20 ans de réclusion sans état de récidive</strong>. Elle est composée de magistrats sans jury."},
  /* GAV SUPPLÉMENTAIRES */
  {id:'g09',cat:'GAV',q:"L'heure de GAV d'un mineur de moins de 16 ans doit être notifiée à :",opts:["L'avocat uniquement","Le PR et les représentants légaux immédiatement","Le médecin scolaire","Le juge des enfants"],c:1,art:"Art. L413-8 CJPM",diff:2,expl:"Pour un mineur de moins de 16 ans, <strong>le PR et les représentants légaux</strong> doivent être informés immédiatement du placement en GAV."},
  {id:'g10',cat:'GAV',q:"En GAV de droit commun, la prolongation (+24h) doit être autorisée :",opts:["Verbalement par le PR","Par écrit et de manière motivée par le PR","Par le JLD uniquement","Automatiquement si l'enquête le nécessite"],c:1,art:"Art. 63 al.2 CPP",diff:1,expl:"La prolongation de 24h doit être accordée <strong>par écrit et de manière motivée</strong> par le Procureur de la République. Une autorisation verbale est insuffisante."},
  /* FICHES SUPPLÉMENTAIRES */
  {id:'fij06',cat:'FICHIERS',q:"Quelle est la durée maximale d'inscription au FIJAISV pour un crime ?",opts:["10 ans","20 ans","30 ans","À vie"],c:2,art:"Art. 706-53-4 CPP",diff:2,expl:"Pour les crimes, l'inscription au FIJAISV dure <strong>30 ans</strong>. Pour les délits, la durée est de 20 ans. Les durées peuvent être réduites par le juge."},
  /* PRESCRIPTION */
  {id:'pr04',cat:'PRESCRIP',q:"La prescription commence à courir pour une infraction continue :",opts:["Au jour du premier acte","Le jour du dernier acte constitutif","Dès la dénonciation","Au jour de la découverte"],c:1,art:"Art. 8 CPP",diff:3,expl:"Pour les infractions continues, la prescription commence à courir à partir du <strong>dernier acte constitutif</strong> de l'infraction (dernier jour de commission)."},
  /* VOIES DE RECOURS */
  {id:'vr01',cat:'INSTRUCTION',q:"Le délai d'appel d'une ordonnance du JI est de :",opts:["5 jours","10 jours","15 jours","30 jours"],c:1,art:"Art. 186 CPP",diff:2,expl:"L'appel d'une ordonnance du Juge d'Instruction doit être formé dans un délai de <strong>10 jours</strong> à compter de la notification de l'ordonnance."},
  /* v300+ — CYBER */
  {id:'cy01',cat:'CYBER',q:"L'accès frauduleux à un système automatisé de données est incriminé à :",opts:["Art. 323-1 CP","Art. 226-18 CP","Art. 434-43 CP","Art. 321-1 CP"],c:0,art:"Art. 323-1 CP",diff:1,expl:"L'<strong>accès frauduleux</strong> à tout ou partie d'un système automatisé de données est puni à l'art. 323-1 CP. Piège : ne pas confondre avec l'atteinte au système (323-2)."},
  {id:'cy02',cat:'CYBER',q:"L'entrave au fonctionnement d'un système informatique (attaque, malware) relève de :",opts:["Art. 323-1 CP","Art. 323-2 CP","Art. 323-4 CP","Art. 226-17 CP"],c:1,art:"Art. 323-2 CP",diff:2,expl:"L'<strong>entrave au fonctionnement</strong> ou l'altération de données est punie à l'art. 323-2 CP. Le 323-1 vise l'accès, le 323-2 l'entrave."},
  {id:'cy03',cat:'CYBER',q:"L'introduction frauduleuse de données dans un système est prévue à :",opts:["Art. 323-2 CP","Art. 323-3 CP","Art. 323-5 CP","Art. 441-7 CP"],c:1,art:"Art. 323-3 CP",diff:2,expl:"L'art. <strong>323-3 CP</strong> sanctionne l'introduction, suppression ou modification frauduleuse de données dans un système."},
  {id:'cy04',cat:'CYBER',q:"La collecte illicite de données à caractère personnel par traitement automatisé est punie à :",opts:["Art. 226-18 CP","Art. 323-4 CP","Art. L226-17 CSI","Art. 434-9 CP"],c:1,art:"Art. 323-4 CP",diff:2,expl:"L'art. <strong>323-4 CP</strong> cible la collecte illicite par traitement automatisé ; à distinguer du fichier nominatif (226-18 à 226-24)."},
  {id:'cy05',cat:'CYBER',q:"Le fait de télécharger illicitement des données dans un système est incriminé à :",opts:["Art. 323-3 CP","Art. 323-5 CP","Art. 323-1 CP","Art. L335-2 CPI"],c:1,art:"Art. 323-5 CP",diff:2,expl:"L'art. <strong>323-5 CP</strong> sanctionne le téléchargement illicite de données dans un système auquel on a accès sans droit ou au-delà de ce droit."},
  {id:'cy06',cat:'CYBER',q:"La détention, offre ou mise à disposition d'un outil conçu pour commettre une intrusion est punie à :",opts:["Art. 323-5-1 CP","Art. 323-7 CP","Art. 322-3-1 CP","Art. 434-40 CP"],c:1,art:"Art. 323-5-1 CP",diff:3,expl:"L'art. <strong>323-5-1 CP</strong> vise la provocation, la publicité ou la mise à disposition d'outils d'intrusion ou de capture de données."},
  {id:'cy07',cat:'CYBER',q:"L'importation ou la détention de logiciels exclusivement destinés à porter atteinte à des données est prévue à :",opts:["Art. 323-6 CP","Art. 323-7 CP","Art. L335-4 CPI","Art. 226-17 CP"],c:1,art:"Art. 323-7 CP",diff:2,expl:"L'art. <strong>323-7 CP</strong> sanctionne l'import, détention, offre ou transfert de logiciels exclusivement destinés à commettre les infractions des 323-1 à 323-6."},
  {id:'cy08',cat:'CYBER',q:"L'usurpation d'identité numérique dans un but frauduleux peut notamment relever de :",opts:["323-1 CP uniquement","323-1 et 226-4-1 CP selon les faits","226-18 CP seulement","434-33 CP uniquement"],c:1,art:"Art. 323-1 / 226-4-1 CP",diff:3,expl:"Selon les hypothèses : <strong>accès frauduleux (323-1)</strong>, usurpation d'identité (226-4-1). L'analyse factuelle détermine la qualification."},
  {id:'cy09',cat:'CYBER',q:"Le cyberharcèlement répété par messages électroniques peut constituer :",opts:["222-33-2 CP uniquement","222-33-2-2 CP (harcèlement moral)","321-6 CP","324-1 CP"],c:1,art:"Art. 222-33-2-2 CP",diff:2,expl:"Le harcèlement moral incluant le cyberharcèlement répété est sanctionné à l'art. <strong>222-33-2-2 CP</strong> (harcèlement moral)."},
  {id:'cy10',cat:'CYBER',q:"La provocation directe au suicide par moyens électroniques peut relever de :",opts:["Art. 223-13 CP","Art. 222-33-2-2 CP","Art. 434-1 CP","Art. 323-2 CP"],c:0,art:"Art. 223-13 CP",diff:2,expl:"La provocation au suicide est incriminée à l'art. <strong>223-13 CP</strong>, quel que soit le canal (y compris numérique)."},
  {id:'cy11',cat:'CYBER',q:"La captation illicite de données sans droit depuis un système s'analyse souvent comme :",opts:["Vol (311-1 CP)","323-4 ou 323-5 CP selon les faits","Abus de confiance seulement","Pas d'infraction pénale"],c:1,art:"Art. 323-4 / 323-5 CP",diff:3,expl:"La captation illicite s'inscrit typiquement dans les <strong>323-4 (collecte) ou 323-5 (téléchargement)</strong>, pas dans le vol au sens 311-1."},
  {id:'cy12',cat:'CYBER',q:"L'altération de données dans un système automatisé au préjudice d'autrui est prévue à :",opts:["323-1 CP","323-2 ou 323-3 CP","226-16 CP","434-9 CP"],c:1,art:"Art. 323-2 / 323-3 CP",diff:2,expl:"L'<strong>altération frauduleuse</strong> relève du 323-2 (entrave) ou 323-3 (introduction/modification de données)."},
  {id:'cy13',cat:'CYBER',q:"Pour l'accès frauduleux (323-1), la peine maximale de droit commun est d'environ :",opts:["1 an d'emprisonnement","2 ans d'emprisonnement et 60 000 € d'amende","5 ans d'emprisonnement","7 ans d'emprisonnement"],c:1,art:"Art. 323-1 CP",diff:1,expl:"L'accès frauduleux simple est puni de <strong>2 ans d'emprisonnement et 60 000 € d'amende</strong> au maximum (droit commun) ; aggravations possibles."},
  {id:'cy14',cat:'CYBER',q:"L'infraction de 323-1 CP exige notamment :",opts:["Un préjudice pécuniaire","Un accès à un système automatisé sans droit ou en excédant le droit","Une modification physique du serveur","Deux témoins"],c:1,art:"Art. 323-1 CP",diff:2,expl:"Il faut un <strong>accès frauduleux</strong> à un système automatisé : sans droit ou en dépassant les droits d'accès."},
  {id:'cy15',cat:'CYBER',q:"La révélation de données protégées obtenues par intrusion peut constituer en plus :",opts:["Uniquement 323-1","226-18 ou atteinte à la vie privée selon les faits","Pas d'autre infraction","434-33 CP systématiquement"],c:1,art:"Art. 226-18 et s. CP",diff:3,expl:"Peut se cumuler avec <strong>atteinte aux données personnelles (226-18 s.)</strong> ou atteinte à la vie privée selon la suite des faits."},
  {id:'cy16',cat:'CYBER',q:"Un salarié consultant le fichier clients au-delà de ses habilitations peut être poursuivi pour :",opts:["311-1 CP","323-1 ou 323-5 CP","Seulement disciplinaire","226-22 CP uniquement"],c:1,art:"Art. 323-1 / 323-5 CP",diff:3,expl:"L'accès <strong>au-delà des droits d'habilitation</strong> relève typiquement du 323-1 ou du téléchargement illicite (323-5)."},
  {id:'cy17',cat:'CYBER',q:"La 'credential stuffing' (réutilisation de fuites de mots de passe) pour accéder à des comptes relève de :",opts:["323-1 CP si accès sans droit","Uniquement contravention","L335-2 CPI","Pas d'infraction en France"],c:0,art:"Art. 323-1 CP",diff:3,expl:"Si l'accès au compte est obtenu <strong>sans droit</strong>, l'élément matériel du 323-1 peut être caractérisé."},
  {id:'cy18',cat:'CYBER',q:"La conservation de preuves numériques par l'OPJ doit respecter notamment :",opts:["Uniquement le secret professionnel","La chaîne de custody et les règles CPP (saisie, copie intègre)","L'anonymat absolu du suspect","Aucune formalité"],c:1,art:"CPP / doctrine",diff:2,expl:"Les preuves informatiques exigent une <strong>intégrité et une traçabilité</strong> (copie forensique, procès-verbal) pour valeur probante."},
  /* MINEURS CJPM */
  {id:'min03',cat:'MINEURS',q:"La retenue judiciaire d'un mineur de moins de 13 ans peut durer au maximum :",opts:["6 heures","12 heures non renouvelables","24 heures","48 heures"],c:1,art:"Art. L413-6 CJPM",diff:2,expl:"Pour les moins de 13 ans, pas de GAV : <strong>retenue judiciaire de 12 h maximum, non renouvelable</strong> (art. L413-6 CJPM)."},
  {id:'min04',cat:'MINEURS',q:"Pour un mineur de 16 à 18 ans, la GAV est possible pour :",opts:["Toute infraction","Toute infraction punie d'emprisonnement","Infractions punies d'au moins 1 an d'emprisonnement","Infractions punies d'au moins 3 ans d'emprisonnement"],c:1,art:"Art. L413-6 CJPM",diff:3,expl:"Les 16-18 ans : GAV si l'infraction est punie d'au moins <strong>1 an d'emprisonnement</strong> (seuil plus bas que pour les 13-16 ans : 5 ans)."},
  {id:'min05',cat:'MINEURS',q:"L'audition d'un mineur en tant que témoin peut exiger :",opts:["Uniquement la présence du PR","La présence d'un représentant légal ou d'un adulte désigné selon les cas","L'absence d'avocat","L'audition par visioconférence obligatoire"],c:1,art:"Art. L211-1 à L211-3 CJPM",diff:2,expl:"Les mineurs témoins bénéficient d'un <strong>accompagnement adapté</strong> (représentant légal, adulte référent selon les règles du CJPM et du CPP)."},
  {id:'min06',cat:'MINEURS',q:"Le tuteur ad hoc peut être désigné lorsque :",opts:["Le mineur est victime uniquement","Les intérêts du mineur et ceux de ses représentants légaux sont en conflit","Le mineur a plus de 16 ans","Jamais en procédure pénale"],c:1,art:"Art. L211-4-1 CJPM",diff:2,expl:"Le <strong>tuteur ad hoc</strong> est désigné en cas de conflit d'intérêts entre le mineur et ses représentants légaux (art. L211-4-1 CJPM)."},
  {id:'min07',cat:'MINEURS',q:"L'administrateur ad hoc intervient notamment pour :",opts:["Représenter le mineur suspect","Représenter l'intérêt du mineur victime lorsque les titulaires de l'autorité parentale sont mis en cause","Remplacer l'avocat","Gérer les biens du mineur"],c:1,art:"Art. L211-5 CJPM",diff:3,expl:"L'<strong>administrateur ad hoc</strong> représente l'intérêt du mineur victime lorsque les parents sont en cause ou en conflit (CJPM)."},
  {id:'min08',cat:'MINEURS',q:"Un mineur de 14 ans entendu comme témoin doit être assisté :",opts:["Obligatoirement par deux avocats","Selon les règles d'audition des mineurs (accompagnement, forme adaptée)","Sans aucun accompagnement","Uniquement par le juge des enfants"],c:1,art:"CPP / CJPM",diff:2,expl:"Les auditions de mineurs témoins doivent être <strong>adaptées à l'âge</strong> avec accompagnement et garanties procédurales."},
  {id:'min09',cat:'MINEURS',q:"Pour un mineur en GAV, la durée est en principe plafonnée et les prolongations sont :",opts:["Libres comme pour un majeur","Exceptionnelles et encadrées (JLD / magistrat selon les cas)","Interdites","De 96 h systématiques"],c:1,art:"Art. L413-6 CJPM",diff:2,expl:"La GAV mineur est <strong>plus courte et plus encadrée</strong> que pour les majeurs ; les prolongations nécessitent des décisions judiciaires selon les hypothèses."},
  {id:'min10',cat:'MINEURS',q:"Le procureur doit être avisé du placement en GAV d'un mineur :",opts:["Dans les 3 h","Immédiatement","Avant toute audition","Le lendemain"],c:1,art:"Art. L413-8 CJPM",diff:1,expl:"Le PR doit être avisé <strong>immédiatement</strong> du placement en GAV d'un mineur."},
  {id:'min11',cat:'MINEURS',q:"L'avis aux représentants légaux pour un mineur de moins de 16 ans en GAV doit être :",opts:["Différé si le PR l'ordonne","Immédiat","Dans les 24 h","Facultatif"],c:1,art:"Art. L413-8 CJPM",diff:2,expl:"Pour moins de 16 ans, l'information des représentants légaux est une exigence <strong>immédiate</strong> (sauf impossibilité exceptionnelle)."},
  {id:'min12',cat:'MINEURS',q:"Un mineur mis en examen a droit notamment à :",opts:["L'assistance d'un avocat d'office obligatoire","Aucun droit particulier","Le même régime qu'un majeur sans avocat","Uniquement un entretien téléphonique"],c:0,art:"Art. L211-2 CJPM",diff:2,expl:"Le mineur mis en examen bénéficie d'un <strong>avocat commis d'office</strong> et de garanties renforcées (CJPM + CPP)."},
  {id:'min13',cat:'MINEURS',q:"La garde à vue d'un mineur de 16 ans pour délit puni de 2 ans d'emprisonnement est :",opts:["Possible","Impossible — seuil 1 an non atteint si le texte exige 1 an","Toujours possible","Réservée au juge des enfants seul"],c:1,art:"Art. L413-6 CJPM",diff:3,expl:"À partir de 16 ans, la GAV est possible si l'infraction est punie d'au moins <strong>1 an</strong> ; un délit à 2 ans remplit le seuil."},
  {id:'min14',cat:'MINEURS',q:"La présomption d'irresponsabilité pénale irréfragable s'applique jusqu'à :",opts:["10 ans","12 ans","13 ans","16 ans"],c:2,art:"Art. L11-1 CJPM",diff:1,expl:"Le CJPM pose la présomption irréfragable d'irresponsabilité pour les moins de <strong>13 ans</strong>."},
  {id:'min15',cat:'MINEURS',q:"Pour un mineur entendu en qualité de victime, l'audition peut être :",opts:["Publique obligatoirement","Vidéo-protégée ou à distance selon décision judiciaire","Sans jamais de médiateur","Réservée au parquet"],c:1,art:"CPP / CJPM",diff:2,expl:"Des modalités <strong>protégées</strong> (audition vidéo, lieu adapté) sont possibles pour limiter la traumatisation."},
  {id:'min16',cat:'MINEURS',q:"Le juge des enfants peut être saisi notamment pour :",opts:["Toutes les infractions des mineurs sans exception","Certaines mesures et procédures concernant la protection de l'enfance","Les crimes uniquement","Les contraventions routières"],c:1,art:"CJPM",diff:2,expl:"Le <strong>juge des enfants</strong> intervient dans le cadre des procédures pénales et mesures propres aux mineurs."},
  {id:'min17',cat:'MINEURS',q:"La distinction principale GAV 13-16 ans vs 16-18 ans concerne notamment :",opts:["L'âge du juge","Le seuil de gravité de l'infraction justifiant la GAV (5 ans vs 1 an)","La durée du silence","L'interdiction d'avocat"],c:1,art:"Art. L413-6 CJPM",diff:2,expl:"13-16 ans : GAV si peine ≥ <strong>5 ans</strong> ; 16-18 ans : si peine ≥ <strong>1 an</strong> (art. L413-6)."},
  {id:'min18',cat:'MINEURS',q:"La retenue au sens CJPM pour moins de 13 ans remplace :",opts:["La garde à vue","La composition pénale","L'audition libre","La médiation"],c:0,art:"Art. L413-6 CJPM",diff:2,expl:"La <strong>GAV est interdite</strong> pour moins de 13 ans ; la retenue judiciaire encadrée la remplace."},
  {id:'min19',cat:'MINEURS',q:"Un mineur témoin vulnérable peut bénéficier :",opts:["D'un témoignage anonyme systématique","D'auditions adaptées et, selon les cas, de l'article 706-52 CPP pour mineurs victimes","De l'absence de PV","D'une garde à vue"],c:1,art:"Art. 706-52 CPP / CJPM",diff:3,expl:"Les mineurs victimes de certains faits peuvent être entendus selon des <strong>modalités protégées</strong> (706-52 pour mineurs victimes de violences ou crimes)."},
  {id:'min20',cat:'MINEURS',q:"Le consentement du représentant légal est requis pour certaines mesures concernant le mineur :",opts:["Jamais","Souvent pour les actes médicaux et mesures éducatives, contexte procédural encadré","Toujours pour la GAV","Uniquement devant la cour d'assises"],c:1,art:"CJPM",diff:2,expl:"L'autorité parentale et le cadre CJPM impliquent le <strong>représentant légal</strong> pour nombre d'actes concernant le mineur."},
  /* VIOLENCES_CONJ */
  {id:'vc01',cat:'VIOLENCES_CONJ',q:"L'ordonnance de protection peut notamment ordonner l'éloignement du domicile conjugal :",opts:["Sans jamais de juge","Par le juge aux affaires familiales (JAF) ou le juge judiciaire selon les cas","Par le seul procureur","Par le maire"],c:1,art:"Art. 515-9 CC",diff:2,expl:"L'<strong>ordonnance de protection</strong> (art. 515-9 CC) peut imposer notamment l'éloignement du conjoint violent du domicile."},
  {id:'vc02',cat:'VIOLENCES_CONJ',q:"La durée maximale initiale d'une ordonnance de protection est en principe de :",opts:["15 jours","6 mois","1 an renouvelable","5 ans"],c:1,art:"Art. 515-9 CC",diff:2,expl:"L'ordonnance de protection est prononcée pour une durée maximale de <strong>6 mois</strong> (renouvelable)."},
  {id:'vc03',cat:'VIOLENCES_CONJ',q:"Le bracelet anti-rapprochement électronique peut être ordonné :",opts:["Uniquement en matière terroriste","Dans le cadre des mesures civiles de protection (art. 515-11-1 CC) ou pénales selon les textes","Par l'OPJ seul","Sans autorisation judiciaire"],c:1,art:"Art. 515-11-1 CC",diff:2,expl:"Le <strong>bracelet anti-rapprochement</strong> est encadré notamment par l'art. 515-11-1 CC pour les violences conjugales."},
  {id:'vc04',cat:'VIOLENCES_CONJ',q:"Une OQTF peut être prononcée à l'encontre d'un étranger condamné pour violences conjugales graves lorsque :",opts:["Jamais","Les conditions légales d'éloignement sont réunies (notamment risque d'ordre public, gravité)","Automatiquement sans jugement","Uniquement si double nationalité"],c:1,art:"CESEDA / jurisprudence",diff:3,expl:"L'<strong>OQTF</strong> pour violences conjugales s'inscrit dans le régime des éloignements du territoire ; les conditions sont appréciées au cas par cas."},
  {id:'vc05',cat:'VIOLENCES_CONJ',q:"La composition pénale pour violences conjugales peut inclure :",opts:["Uniquement une amende","Des mesures de soins, d'interdiction de lieu ou de contact selon le catalogue","Rien d'obligatoire","La prison ferme immédiate"],c:1,art:"Art. 41-2 CPP",diff:2,expl:"La <strong>composition pénale</strong> peut proposer des mesures adaptées (soins, mesures de sûreté civiles) hors délais de prescription."},
  {id:'vc06',cat:'VIOLENCES_CONJ',q:"L'ordonnance de protection peut être demandée par :",opts:["Seulement le ministère public","La victime ou le ministère public selon les procédures","Uniquement un avocat","Le préfet seul"],c:1,art:"Art. 515-9 CC",diff:2,expl:"La <strong>demande</strong> peut émaner de la victime ou du parquet selon les voies (référé, procédure pénale connexe)."},
  {id:'vc07',cat:'VIOLENCES_CONJ',q:"Le délai pour former une opposition à une ordonnance de protection sur requête est :",opts:["10 jours","15 jours","1 mois","3 mois"],c:1,art:"Art. 515-9 CC",diff:3,expl:"L'opposition doit être formée dans un délai de <strong>15 jours</strong> à compter de la signification (sauf évolution législative à vérifier)."},
  {id:'vc08',cat:'VIOLENCES_CONJ',q:"Les violences psychologiques répétées dans le couple peuvent constituer :",opts:["Uniquement une contravention","Des violences volontaires avec circonstances ou harcèlement moral selon les faits","Pas d'infraction","Un délit de presse"],c:1,art:"Art. 222-14 / 222-33-2-2 CP",diff:2,expl:"Les <strong>violences morales</strong> répétées peuvent relever du harcèlement moral (222-33-2-2) ou de coups et blessures psychologiques."},
  {id:'vc09',cat:'VIOLENCES_CONJ',q:"L'interdiction de paraître au domicile du conjoint peut être :",opts:["Orale","Civile (515-9) et/ou pénale (RTJ, contrôle judiciaire)","Réservée au divorce uniquement","Décision du préfet de police seul"],c:1,art:"Art. 515-9 CC / CPP",diff:2,expl:"L'<strong>éloignement</strong> peut résulter de mesures civiles de protection ou de mesures pénales."},
  {id:'vc10',cat:'VIOLENCES_CONJ',q:"Le juge civil peut assortir l'ordonnance de protection d'une astreinte :",opts:["Jamais","Oui pour les manquements aux mesures","Uniquement en cas de divorce","Seulement si partie civile"],c:1,art:"Art. 515-9 CC",diff:2,expl:"Le juge peut prononcer une <strong>astreinte</strong> en cas de non-respect des mesures."},
  {id:'vc11',cat:'VIOLENCES_CONJ',q:"Les violences conjugales aggravées (sur conjoint, concubin) sont prévues à :",opts:["311-1 CP","222-14-3 CP","324-1 CP","434-1 CP"],c:1,art:"Art. 222-14-3 CP",diff:1,expl:"Les violences sur <strong>conjoint ou concubin</strong> sont aggravées à l'art. 222-14-3 CP."},
  {id:'vc12',cat:'VIOLENCES_CONJ',q:"La main courante au commissariat pour violences conjugales :",opts:["Vaut plainte pénale","Trace les faits et peut orienter vers une plainte","Éteint l'action publique","Remplace l'enquête"],c:1,art:"Doctrine / procédure",diff:2,expl:"La <strong>main courante</strong> ne vaut pas plainte mais crée une trace et peut être suivie d'une plainte."},
  {id:'vc13',cat:'VIOLENCES_CONJ',q:"L'ordre de protection peut prévoir la remise des armes détenues légalement :",opts:["Non","Oui, saisie ou dépôt aux autorités","Uniquement pour les armes de guerre","Automatiquement sans juge"],c:1,art:"Art. 515-9 CC",diff:2,expl:"L'ordonnance peut prévoir la <strong>saisie ou le dépôt des armes</strong> détenues par le violent."},
  {id:'vc14',cat:'VIOLENCES_CONJ',q:"Le téléphone grave danger (TGD) relève d'un dispositif :",opts:["Pénal obligatoire","D'aide aux victimes de violences conjugales sous conditions","Réservé aux majeurs uniquement","Désactivé depuis 2020"],c:1,art:"Décret TGD",diff:1,expl:"Le <strong>TGD</strong> permet un appel prioritaire aux forces de l'ordre pour les victimes en très haut risque."},
  {id:'vc15',cat:'VIOLENCES_CONJ',q:"La composition pénale pour violences ne peut concerner que :",opts:["Les crimes uniquement","Les délits punis dans les limites de l'art. 41-2 CPP","Les contraventions seulement","Les infractions fiscales"],c:1,art:"Art. 41-2 CPP",diff:2,expl:"La <strong>composition pénale</strong> s'applique aux délits dans la limite de peine prévue (5 ans max d'emprisonnement)."},
  /* STUPS — enquêtes spéciales */
  {id:'stp01',cat:'STUPS',q:"L'enquête de flagrance pour les infractions de stupéfiants est prévue à :",opts:["Art. 53 CPP","Art. 706-26 CPP","Art. 80 CPP","Art. 59 CPP"],c:1,art:"Art. 706-26 CPP",diff:2,expl:"L'art. <strong>706-26 CPP</strong> encadre les enquêtes pour trafic de stupéfiants (avec d'autres articles du même chapitre)."},
  {id:'stp02',cat:'STUPS',q:"L'infiltration par un agent de police peut être autorisée pour :",opts:["Toute infraction","Les infractions de criminalité organisée ou stupéfiants selon les conditions strictes","Les contraventions","Sans juge"],c:1,art:"Art. 706-32 CPP",diff:2,expl:"L'<strong>infiltration</strong> (706-32) est encadrée : durée limitée, autorisation judiciaire, rapport final."},
  {id:'stp03',cat:'STUPS',q:"L'utilisation d'un pseudonyme par un enquêteur est autorisée dans le cadre :",opts:["Art. 706-87-1 CPP","Art. 59 CPP","Art. 63 CPP","Art. 76 CPP"],c:0,art:"Art. 706-87-1 CPP",diff:2,expl:"L'art. <strong>706-87-1 CPP</strong> permet l'usage d'un pseudonyme pour certains actes d'enquête sous conditions."},
  {id:'stp04',cat:'STUPS',q:"La supervision judiciaire internationale (transmission d'enquête) relève notamment de :",opts:["L'art. 695-9-1 CPP uniquement","La coopération judiciaire européenne et les conventions","L'art. 53 CPP","Le seul Interpol"],c:1,art:"CPP titre XXIV",diff:3,expl:"La <strong>supervision</strong> des enquêtes sous contrôle d'un magistrat étranger est encadrée par les conventions et le CPP (titres sur l'entraide)."},
  {id:'stp05',cat:'STUPS',q:"Les écoutes téléphoniques en matière de stupéfiants en préliminaire peuvent être ordonnées par :",opts:["L'OPJ seul","Le JLD sur réquisition du PR (art. 706-95 et s.)","Le maire","Le préfet sans juge"],c:1,art:"Art. 706-95 CPP",diff:2,expl:"Les <strong>interceptions</strong> nécessitent une ordonnance du JLD sur réquisition du PR pour les infractions en cause."},
  {id:'stp06',cat:'STUPS',q:"Les opérations d'infiltration ont une durée maximale par autorisation de :",opts:["15 jours","4 mois renouvelable une fois","1 an","Illimitée"],c:1,art:"Art. 706-32 CPP",diff:3,expl:"L'infiltration est limitée dans le temps (schéma <strong>4 mois + renouvellement</strong> selon le texte applicable)."},
  {id:'stp07',cat:'STUPS',q:"Les stupéfiants en bande organisée relèvent typiquement de :",opts:["706-26 seul","706-26 et circonstances d'organisation (706-73 s.)","Seulement du code de la santé publique","Contraventions"],c:1,art:"Art. 706-26 / 706-73 CPP",diff:2,expl:"Le trafic aggravé en <strong>bande organisée</strong> mobilise le régime d'enquête renforcé et la CO."},
  {id:'stp08',cat:'STUPS',q:"L'identité de l'agent infiltré peut être :",opts:["Divulguée librement","Protégée ; pseudonyme et mentions limitées au dossier","Publique d'office","Inscrite au TAJ"],c:1,art:"Art. 706-32 CPP",diff:2,expl:"L'<strong>anonymat opérationnel</strong> de l'agent est protégé ; les PV et dossiers utilisent des mentions adaptées."},
  {id:'stp09',cat:'STUPS',q:"Les perquisitions nocturnes pour trafic de stupéfiants graves peuvent être autorisées :",opts:["Jamais","Par le JLD ou le juge d'instruction selon les cas et textes","Par le PR seul","Par le gouverneur"],c:1,art:"Art. 706-30 et s. CPP",diff:3,expl:"Les <strong>perquisitions de nuit</strong> en matière de stupéfiants sont encadrées et nécessitent une autorisation judiciaire."},
  {id:'stp10',cat:'STUPS',q:"Le contrôle d'identité aux fins de recherche de stupéfiants sur voie publique doit respecter :",opts:["Aucune limite","Art. 78-2 CPP et conditions de légalité","Uniquement le consentement","L'avis du maire"],c:1,art:"Art. 78-2 CPP",diff:2,expl:"Le <strong>contrôle</strong> doit rester fondé et proportionné (art. 78-2 et jurisprudence)."},
  {id:'stp11',cat:'STUPS',q:"La gardiennage sous contrôle judiciaire pour trafic peut s'accompagner :",opts:["D'aucune mesure","De bracelet électronique et interdictions de contact","D'une amende forfaitaire","D'un simple avertissement"],c:1,art:"CPP / contrôle judiciaire",diff:2,expl:"Le <strong>contrôle judiciaire</strong> peut combiner résidence surveillée et interdictions."},
  {id:'stp12',cat:'STUPS',q:"Les agents utilisant un pseudonyme doivent :",opts:["Signaler leur identité réelle au suspect","Respecter le cadre de l'art. 706-87-1 et la traçabilité interne","Agir sans PV","Refuser toute audition"],c:1,art:"Art. 706-87-1 CPP",diff:3,expl:"Le <strong>pseudonyme</strong> est encadré : traçabilité en interne, identité réelle connue du magistrat et du dossier restreint."},
  {id:'stp13',cat:'STUPS',q:"L'interdiction de séjour pour trafic peut être prononcée comme :",opts:["Peine complémentaire","Peine complémentaire ou mesure de sûreté selon les textes","Contravention","Mesure civile uniquement"],c:1,art:"Art. 131-30 CP",diff:2,expl:"L'<strong>interdiction du territoire</strong> peut être une peine complémentaire pour certaines infractions."},
  {id:'stp14',cat:'STUPS',q:"L'enquête préliminaire pour narcotrafic peut utiliser :",opts:["Uniquement la flagrance","Les techniques spéciales si conditions légales réunies","Sans magistrat","Les mêmes pouvoirs qu'en instruction sans limite"],c:1,art:"Art. 706-26 s. CPP",diff:2,expl:"Les <strong>techniques spéciales</strong> (écoutes, filatures renforcées) nécessitent autorisation judiciaire."},
  {id:'stp15',cat:'STUPS',q:"La livraison surveillée (controlled delivery) s'inscrit dans :",opts:["La seule coutume","Les techniques d'enquête internationales coopératives","L'art. 53 CPP","Interdit en France"],c:1,art:"Conventions / OCRTIS",diff:3,expl:"La <strong>livraison surveillée</strong> est une technique de lutte contre le narcotrafic encadrée coopérativement."},
  /* ATTEINTES_LIBERTE */
  {id:'att01',cat:'ATTEINTES_LIBERTE',q:"La séquestration est définie à :",opts:["Art. 224-1 CP","Art. 222-14 CP","Art. 311-1 CP","Art. 434-6 CP"],c:0,art:"Art. 224-1 CP",diff:1,expl:"La <strong>séquestration</strong> (détention arbitraire) est incriminée à l'art. 224-1 CP."},
  {id:'att02',cat:'ATTEINTES_LIBERTE',q:"L'enlèvement et la séquestration sont punis notamment à :",opts:["Art. 224-2 CP","Art. 224-1 CP uniquement","Art. 222-7 CP","Art. 223-1 CP"],c:0,art:"Art. 224-1 à 224-4 CP",diff:2,expl:"L'<strong>enlèvement</strong> et la séquestration relèvent des arts. 224-1 s. CP avec peines aggravées selon les circonstances."},
  {id:'att03',cat:'ATTEINTES_LIBERTE',q:"La séquestration avec tortures ou actes de barbarie est aggravée :",opts:["Non","Oui — circonstances ou infractions distinctes selon les faits","Comme simple violences","Par une amende forfaitaire"],c:1,art:"Art. 224-1 CP",diff:2,expl:"Les <strong>sévices</strong> ou barbarie aggravent très fortement la répression (réclusion criminelle à perpétuité possible)."},
  {id:'att04',cat:'ATTEINTES_LIBERTE',q:"La prise d'otages (hors contexte terroriste spécifique) peut analyser comme :",opts:["224-1 seulement","Séquestration aggravée ou infractions spéciales selon les hypothèses","Contravention","434-1 CP"],c:1,art:"Art. 224-1 / 444-1 CP",diff:3,expl:"La <strong>prise d'otages</strong> terroriste relève de textes spéciaux ; sinon analyse en séquestration aggravée ou autres qualifications."},
  {id:'att05',cat:'ATTEINTES_LIBERTE',q:"L'élément moral de la séquestration suppose :",opts:["Une erreur de droit","Une intention de retenir la personne contre sa volonté","Un motif économique uniquement","L'absence de déplacement"],c:1,art:"Art. 224-1 CP",diff:2,expl:"Il faut la <strong>volonté de priver de liberté</strong> contre le gré de la victime."},
  {id:'att06',cat:'ATTEINTES_LIBERTE',q:"La durée de la séquestration influence :",opts:["Rien","La qualification et la peine (aggravations pour durée prolongée)","Uniquement la prescription civile","Le tribunal des prud'hommes"],c:1,art:"Art. 224-1 CP",diff:2,expl:"Une <strong>durée longue</strong> ou des sévices sont des facteurs d'aggravation."},
  {id:'att07',cat:'ATTEINTES_LIBERTE',q:"L'enlèvement de mineur par un tiers sans droit peut constituer :",opts:["Uniquement une faute civile","Enlèvement ou détention illicite selon les faits","Une simple injonction","Rien si consentement parent"],c:1,art:"Art. 224-2 CP / 227-5 CP",diff:3,expl:"L'<strong>enlèvement mineur</strong> est incriminé (notamment 227-5 pour non-représentation d'enfant)."},
  {id:'att08',cat:'ATTEINTES_LIBERTE',q:"La rétention de personnes dans un local sans autorisation peut être :",opts:["Légale sans PV","Séquestration ou arrestation arbitraire","Une activité commerciale","Protégée par le secret défense"],c:1,art:"Art. 224-1 CP",diff:2,expl:"Toute <strong>privation de liberté</strong> sans base légale relève de la détention arbitraire."},
  {id:'att09',cat:'ATTEINTES_LIBERTE',q:"La contrainte physique pour empêcher quelqu'un de sortir d'une pièce :",opts:["Est une simple altercation","Peut constituer une séquestration même brève","Est une infraction de presse","N'est jamais pénale"],c:1,art:"Art. 224-1 CP",diff:2,expl:"La <strong>contrainte</strong> au maintien dans un lieu peut suffire à caractériser la séquestration."},
  {id:'att10',cat:'ATTEINTES_LIBERTE',q:"L'enlèvement avec demande de rançon peut s'analyser comme :",opts:["Vol uniquement","Séquestration ou extorsion selon les faits","Délit de fuite","Abus de confiance"],c:1,art:"Art. 224-1 / 312-1 CP",diff:3,expl:"Le <strong>chantage à la rançon</strong> combine souvent séquestration et extorsion."},
  {id:'att11',cat:'ATTEINTES_LIBERTE',q:"La peine maximale de la séquestration simple (sans circonstances) est de :",opts:["5 ans","20 ans de réclusion","7 ans d'emprisonnement et 100 000 € d'amende","Perpétuité"],c:2,art:"Art. 224-1 CP",diff:1,expl:"La séquestration simple est punie jusqu'à <strong>20 ans de réclusion criminelle</strong> (évolution législative à contrôler au moment de l'examen)."},
  {id:'att12',cat:'ATTEINTES_LIBERTE',q:"La libération volontaire de la victime avant intervention des forces de l'ordre peut influencer :",opts:["La prescription uniquement","L'appréciation des circonstances et la poursuite","L'irresponsabilité pénale","La compétence du tribunal"],c:1,art:"Art. 224-1 CP / opportunité des poursuites",diff:3,expl:"La <strong>libération</strong> précoce peut être un élément d'appréciation pour le parquet et les circonstances atténuantes."},
  {id:'att13',cat:'ATTEINTES_LIBERTE',q:"Le délit d'enlèvement ou de détention arbitraire d'un magistrat, gendarme ou policier :",opts:["224-1 simple","224-4 CP (infractions spéciales)","311-6 CP","434-33 CP"],c:1,art:"Art. 224-4 CP",diff:2,expl:"Des <strong>qualifications spéciales</strong> existent pour les détentions de personnes dépositaires de l'autorité publique."},
  /* INFRACTIONS_PUB */
  {id:'ipp01',cat:'INFRACTIONS_PUB',q:"La prise illégale d'intérêt par un fonctionnaire est incriminée à :",opts:["Art. 432-12 CP","Art. 433-1 CP","Art. 434-9 CP","Art. 441-1 CP"],c:0,art:"Art. 432-12 CP",diff:1,expl:"La <strong>prise illégale d'intérêt</strong> est punie à l'art. 432-12 CP."},
  {id:'ipp02',cat:'INFRACTIONS_PUB',q:"La corruption passive (fonctionnaire qui reçoit une offre indue) relève de :",opts:["432-11 CP","433-1 CP","434-33 CP","226-13 CP"],c:0,art:"Art. 432-11 CP",diff:2,expl:"La <strong>corruption passive</strong> des personnes dépositaires de l'autorité publique est à l'art. 432-11 CP."},
  {id:'ipp03',cat:'INFRACTIONS_PUB',q:"La corruption active (donner un avantage indu) est incriminée à :",opts:["432-11 CP","433-1 CP","432-12 CP","434-1 CP"],c:1,art:"Art. 433-1 CP",diff:2,expl:"La <strong>corruption active</strong> est punie à l'art. 433-1 CP (donner sans droit)."},
  {id:'ipp04',cat:'INFRACTIONS_PUB',q:"Le trafic d'influence par un fonctionnaire est prévu à :",opts:["432-10 CP","433-1 CP","434-9 CP","L221-2 CP"],c:1,art:"Art. 433-1 CP",diff:2,expl:"Le <strong>trafic d'influence</strong> (donner/recevoir pour abuser d'une influence réelle ou supposée) est sanctionné notamment par 433-1."},
  {id:'ipp05',cat:'INFRACTIONS_PUB',q:"Le favoritisme (passage de marché sans publicité) concerne :",opts:["Les seuls maires","Les personnes chargées de préparer ou conclure des marchés publics","Les particuliers","Les avocats"],c:1,art:"Art. 432-14 CP",diff:2,expl:"Le <strong>favoritisme</strong> vise les personnes ayant un rôle dans la passation des marchés (432-14)."},
  {id:'ipp06',cat:'INFRACTIONS_PUB',q:"Le détournement de fonds publics par un comptable public est :",opts:["Abus de confiance seulement","Une infraction spécifique (432-15 s.)","Une contravention","Un délit de presse"],c:1,art:"Art. 432-15 CP",diff:2,expl:"Le <strong>détournement</strong> de fonds publics est incriminé spécifiquement pour les comptables publics."},
  {id:'ipp07',cat:'INFRACTIONS_PUB',q:"Confier un marché en violation des règles de concurrence peut constituer :",opts:["Rien","Prise illégale d'intérêt ou favoritisme selon les faits","Uniquement disciplinaire","Un délit routier"],c:1,art:"Art. 432-12 / 432-14 CP",diff:3,expl:"Selon le rôle et le profit : <strong>432-12 (intérêt)</strong> ou 432-14 (favoritisme)."},
  {id:'ipp08',cat:'INFRACTIONS_PUB',q:"L'association de fonctionnaires pour commettre des corruptions :",opts:["N'existe pas","Peut constituer une circonstance aggravée ou une infraction particulière","Est une simple faute","Tombe sous le secret médical"],c:1,art:"Art. 433-1 CP",diff:3,expl:"Les <strong>bandes organisées</strong> de fonctionnaires corrompus peuvent être particulièrement réprimées."},
  {id:'ipp09',cat:'INFRACTIONS_PUB',q:"Recevoir une rémunération occulte pour une décision administrative relève typiquement de :",opts:["Donation","Corruption ou prise d'intérêt selon les faits","Rien si moins de 100 €","Uniquement le fisc"],c:1,art:"Art. 432-11 / 433-1 CP",diff:2,expl:"L'<strong>avantage indu</strong> en lien avec la fonction est au cœur de la corruption."},
  {id:'ipp10',cat:'INFRACTIONS_PUB',q:"La personne morale (collectivité) peut être :",opts:["Toujours poursuivie seule","Poursuivie pénalement pour certaines infractions selon les textes","Exonérée d'office","Jugée par le tribunal des prud'hommes"],c:1,art:"Art. 121-2 CP",diff:2,expl:"La <strong>responsabilité pénale des personnes morales</strong> existe pour les infractions prévues par la loi."},
  {id:'ipp11',cat:'INFRACTIONS_PUB',q:"Le traffic d'influence commis par un particulier (non fonctionnaire) peut relever de :",opts:["433-2 CP","433-1 CP","434-1 CP","Rien"],c:1,art:"Art. 433-2 CP",diff:2,expl:"Le <strong>trafic d'influence</strong> par un particulier est visé à l'art. 433-2 CP."},
  {id:'ipp12',cat:'INFRACTIONS_PUB',q:"Le fait pour un élu de prendre un intérêt dans une affaire qu'il doit traiter est :",opts:["Toujours légal","Une prise illégale d'intérêt possible (432-12)","Une simple déontologie interne","Un délit de fuite"],c:1,art:"Art. 432-12 CP",diff:2,expl:"Les <strong>élus</strong> peuvent encourir 432-12 s'ils participent à une décision où ils ont un intérêt direct."},
  {id:'ipp13',cat:'INFRACTIONS_PUB',q:"La concussion (exiger des fonds non dus) est :",opts:["432-10 CP","Une infraction distincte de la corruption","Une simple erreur de paie","Réglementée par le seul budget"],c:1,art:"Art. 432-10 CP",diff:2,expl:"La <strong>concussion</strong> sanctionne l'exaction de sommes non décomptées (432-10)."},
  /* INSTRUCTION */
  {id:'ins04',cat:'INSTRUCTION',q:"La mise en examen est prononcée s'il existe :",opts:["Un simple doute","Des indices graves ou concordants","Une preuve irréfutable","Un aveu seul"],c:1,art:"Art. 80-1 CPP",diff:1,expl:"La MEX exige des <strong>indices graves ou concordants</strong> (art. 80-1 CPP)."},
  {id:'ins05',cat:'INSTRUCTION',q:"Le témoin assisté est prévu à :",opts:["Art. 109 CPP","Art. 113-1 CPP","Art. 156 CPP","Art. 173 CPP"],c:1,art:"Art. 113-1 CPP",diff:1,expl:"Le statut de <strong>témoin assisté</strong> est défini à l'art. 113-1 CPP."},
  {id:'ins06',cat:'INSTRUCTION',q:"Un mis en examen a le droit de :",opts:["Refuser tout avocat","Être assisté par un avocat et se taire","Être condamné sans être entendu","Ignorer les charges"],c:1,art:"Art. 116 CPP",diff:2,expl:"Les droits du MEX incluent <strong>assistance d'avocat</strong> et droit au silence (art. 116 s.)."},
  {id:'ins07',cat:'INSTRUCTION',q:"La confrontation entre le mis en examen et la victime peut être ordonnée par :",opts:["L'OPJ seul","Le juge d'instruction","Le préfet","Le médecin légiste"],c:1,art:"Art. 114 CPP",diff:2,expl:"La <strong>confrontation</strong> est ordonnée par le JI (art. 114 CPP)."},
  {id:'ins08',cat:'INSTRUCTION',q:"L'expertise technique est ordonnée par :",opts:["Le PR seul","Le juge d'instruction ou la juridiction de jugement selon les phases","L'OPJ","Le témoin"],c:1,art:"Art. 156 CPP",diff:2,expl:"L'<strong>expertise</strong> est ordonnée par le JI en instruction (art. 156) ou par le tribunal au fond."},
  {id:'ins09',cat:'INSTRUCTION',q:"Le mis en examen peut demander des actes d'enquête :",opts:["Jamais","Oui (demandes d'actes, art. 82 et s.)","Uniquement par écrit privé","Seulement après jugement"],c:1,art:"Art. 82 CPP",diff:2,expl:"Le MEX peut formuler des <strong>demandes d'actes</strong> (art. 82 CPP)."},
  {id:'ins10',cat:'INSTRUCTION',q:"L'audition de témoin assisté permet notamment :",opts:["De l'incarcérer sans juge","De clarifier son statut entre témoin et suspect","D'éviter toute audition","De le juger immédiatement"],c:1,art:"Art. 113-1 CPP",diff:3,expl:"Le <strong>témoin assisté</strong> est informé qu'il peut faire l'objet d'une MEX ; il conserve des droits de défense."},
  {id:'ins11',cat:'INSTRUCTION',q:"L'expertise psychiatrique du mis en examen peut être :",opts:["Interdite","Ordonnée par le JI si nécessaire à la manifestation de la vérité","Demandée par le seul avocat de la victime","Réservée aux crimes de sang"],c:1,art:"Art. 157 CPP",diff:2,expl:"L'<strong>expertise psychiatrique</strong> est encadrée (arts. 157 s. CPP)."},
  {id:'ins12',cat:'INSTRUCTION',q:"Le non-lieu peut être ordonné si :",opts:["Le juge en a envie","Les charges sont insuffisantes ou l'infraction n'est pas établie","Le PR refuse le dossier","Le suspect est riche"],c:1,art:"Art. 177 CPP",diff:2,expl:"Le <strong>non-lieu</strong> intervient lorsque les charges sont insuffisantes ou l'infraction non caractérisée."},
  {id:'ins13',cat:'INSTRUCTION',q:"La mise en examen doit être notifiée :",opts:["Oralement seulement","Par notification avec énonciation des faits et des droits","Par SMS","Par le voisin"],c:1,art:"Art. 80-1 CPP",diff:2,expl:"La MEX fait l'objet d'une <strong>notification régulière</strong> (art. 80-1 et suite)."},
  {id:'ins14',cat:'INSTRUCTION',q:"Le juge d'instruction peut être saisi par :",opts:["Seulement le parquet","Réquisitoire introductif ou plainte avec constitution de partie civile","Le préfet","Interpol"],c:1,art:"Art. 80 CPP",diff:1,expl:"La saisine est <strong>réquisitoire introductif</strong> ou CPC (art. 80)."},
  {id:'ins15',cat:'INSTRUCTION',q:"La confrontation n'est pas une :",opts:["Preuve légale","Peine","Mesure d'enquête","Audience publique obligatoire"],c:1,art:"Art. 114 CPP",diff:2,expl:"La <strong>confrontation</strong> est un acte d'instruction pour confronter les versions."},
  {id:'ins16',cat:'INSTRUCTION',q:"L'expert peut être écarté si :",opts:["Jamais","Il y a cause de récusation ou partialité","Il est trop lent","Il est étranger"],c:1,art:"Art. 158 CPP",diff:3,expl:"La <strong>récusation</strong> de l'expert est possible pour cause légitime."},
  {id:'ins17',cat:'INSTRUCTION',q:"Le mis en examen peut être placé sous contrôle judiciaire par :",opts:["L'OPJ","Le juge d'instruction ou le JLD selon les phases","Le maire","Le médiateur"],c:1,art:"Art. 142 CPP",diff:2,expl:"Le <strong>contrôle judiciaire</strong> est décidé par le JI ou le JLD selon les moments."},
  {id:'ins18',cat:'INSTRUCTION',q:"Les actes d'enquête de police en instruction sont validés par :",opts:["Aucun contrôle","Le juge d'instruction dans le dossier d'instruction","Le journal local","Le suspect seul"],c:1,art:"CPP",diff:2,expl:"En instruction, les actes sont <strong>centralisés et contrôlés</strong> par le JI."},
  /* CRIMORG */
  {id:'cro01',cat:'CRIMORG',q:"La criminalité organisée est définie à :",opts:["Art. 706-73 CPP","Art. 53 CPP","Art. 450-1 CP","Art. 706-26 CPP"],c:0,art:"Art. 706-73 CPP",diff:1,expl:"La définition procédurale de la <strong>criminalité organisée</strong> est à l'art. 706-73 CPP."},
  {id:'cro02',cat:'CRIMORG',q:"Les infractions entrant dans le champ de la criminalité organisée incluent notamment :",opts:["Toutes les contraventions","Les infractions punies d'au moins 5 ans d'emprisonnement listées (stupéfiants, proxénétisme, etc.)","Les stationnements","Les délits de presse"],c:1,art:"Art. 706-73 CPP",diff:2,expl:"La liste renvoie à des <strong>infractions graves</strong> (stupéfiants, étrangers en bande, etc.)."},
  {id:'cro03',cat:'CRIMORG',q:"Les JIRS sont :",opts:["Des juridictions interrégionales spécialisées (stupéfiants, finances)","Des tribunaux de commerce","Des communes","Des centres de détention"],c:0,art:"Art. 706-73 et org. judiciaire",diff:2,expl:"Les <strong>JIRS</strong> sont des juridictions interrégionales spécialisées pour la criminalité organisée et les grands trafics."},
  {id:'cro04',cat:'CRIMORG',q:"La sonorisation d'un véhicule en enquête CO peut être autorisée par :",opts:["Le PR seul","Le JLD pour une durée limitée (art. 706-96)","L'OPJ sans juge","Le conducteur"],c:1,art:"Art. 706-96 CPP",diff:2,expl:"La <strong>sonorisation</strong> du véhicule nécessite une ordonnance du JLD (706-96)."},
  {id:'cro05',cat:'CRIMORG',q:"La géolocalisation en temps réel au-delà de 15 jours en matière CO nécessite :",opts:["Rien","Le JLD au-delà de la première période (art. 230-32 CPP)","Le préfet","Un simple PV"],c:1,art:"Art. 230-32 CPP",diff:2,expl:"Le PR autorise jusqu'à <strong>15 jours</strong> ; au-delà, le <strong>JLD</strong> est obligatoire."},
  {id:'cro06',cat:'CRIMORG',q:"L'association de malfaiteurs en bande organisée est punie à :",opts:["Art. 450-1 CP","Art. 706-73 CPP","Art. 311-9 CP","Art. 434-1 CP"],c:0,art:"Art. 450-1 CP",diff:1,expl:"L'<strong>association de malfaiteurs</strong> criminelle est incriminée à l'art. 450-1 CP."},
  {id:'cro07',cat:'CRIMORG',q:"Les techniques spéciales d'enquête en CO incluent :",opts:["Uniquement la flagrance","Écoutes, filatures, infiltrations, géolocalisation selon autorisation","Des contrôles d'identité illimités","L'audition sans PV"],c:1,art:"Art. 706-80 s. CPP",diff:2,expl:"Le régime CO permet des <strong>techniques renforcées</strong> sous contrôle judiciaire."},
  {id:'cro08',cat:'CRIMORG',q:"Le JLD compétent pour les mesures CO est :",opts:["Toujours à Paris","Le JLD du tribunal judiciaire du lieu de l'enquête ou selon règles de compétence","Le tribunal de commerce","La cour d'appel seule"],c:1,art:"Art. 706-75 CPP",diff:3,expl:"La <strong>compétence du JLD</strong> est liée au siège du tribunal de grande instance du lieu des opérations."},
  {id:'cro09',cat:'CRIMORG',q:"L'infiltration nécessite une durée maximale d' :",opts:["Illimitée","4 mois renouvelable une fois selon le texte","1 jour","10 ans"],c:1,art:"Art. 706-32 CPP",diff:3,expl:"L'<strong>infiltration</strong> est strictement limitée dans le temps."},
  {id:'cro10',cat:'CRIMORG',q:"L'enquête préliminaire pour CO peut être ouverte par :",opts:["Le maire","Le procureur de la République","Le suspect","Le médiateur"],c:1,art:"Art. 706-80 CPP",diff:2,expl:"L'ouverture est souvent du ressort du <strong>parquet</strong> et des services spécialisés."},
  {id:'cro11',cat:'CRIMORG',q:"La qualification en bande organisée suppose notamment :",opts:["3 personnes sans structure","Une structure organisée et une infraction de base","Une simple connaissance","Un contrat écrit"],c:1,art:"Art. 450-1 CP / 706-73 CPP",diff:3,expl:"Il faut une <strong>entente structurée</strong> et l'commission d'infractions punies d'au moins 5 ans."},
  {id:'cro12',cat:'CRIMORG',q:"Les interceptions téléphoniques en CO sont décidées par :",opts:["L'OPJ","Le JLD sur réquisition motivée","Le préfet","Le ministre seul"],c:1,art:"Art. 706-95 CPP",diff:2,expl:"Les <strong>écoutes</strong> nécessitent ordonnance du JLD."},
  {id:'cro13',cat:'CRIMORG',q:"L'office central de lutte contre la criminalité organisée (OCLCO) dépend :",opts:["Du maire","De la DCPJ / ministère de l'Intérieur","Des tribunaux de commerce","De l'UE uniquement"],c:1,art:"Organisation",diff:2,expl:"L'<strong>OCLCO</strong> est un service central de police judiciaire."},
  {id:'cro14',cat:'CRIMORG',q:"La géolocalisation d'un véhicule sans sonorisation peut être autorisée pour :",opts:["0 jour","Durées encadrées par le JLD (30 jours renouvelable selon les textes)","10 ans","Sans limite"],c:1,art:"Art. 230-32 CPP",diff:3,expl:"La <strong>géolocalisation</strong> est limitée dans le temps par ordonnance judiciaire."},
  {id:'cro15',cat:'CRIMORG',q:"L'infiltré ne peut pas :",opts:["Provoquer une infraction (agent provocateur interdit)","Enquêter","Rédiger un PV","Être protégé"],c:0,art:"Art. 706-32 CPP",diff:3,expl:"L'agent ne doit pas <strong>inciter</strong> à commettre une infraction (pas d'agent provocateur)."},
  /* EUROP */
  {id:'eu01',cat:'EUROP',q:"Le mandat d'arrêt européen (MAE) est prévu à :",opts:["Art. 694-1 CPP","Art. 695-11 CPP","Art. 53 CPP","Art. 131 CPP"],c:1,art:"Art. 695-11 CPP",diff:1,expl:"Le <strong>MAE</strong> est encadré par les arts. 695-11 s. CPP."},
  {id:'eu02',cat:'EUROP',q:"Le MAE peut être émis pour des infractions punies d'au minimum :",opts:["6 mois de prison","1 an d'emprisonnement (liste positive) ou selon les cas 3 ans","10 jours","Contraventions"],c:1,art:"Décision-cadre 2002/584/JAI",diff:2,expl:"Le MAE vise des <strong>infractions graves</strong> selon la liste et les peines minimales prévues par la décision-cadre."},
  {id:'eu03',cat:'EUROP',q:"La personne arrêtée sur MAE peut consentir à sa remise :",opts:["Jamais","Oui (consentement à la remise, procédure accélérée)","Uniquement après extradition vers les USA","Seulement si mineur"],c:1,art:"Art. 695-23 CPP",diff:2,expl:"Le <strong>consentement</strong> à la remise permet une procédure simplifiée."},
  {id:'eu04',cat:'EUROP',q:"L'entraide judiciaire en matière pénale avec un État UE repose sur :",opts:["Le seul bon vouloir","Instruments européens et conventions (EOM, ENMI)","Facebook","Le téléphone arabe"],c:1,art:"CPP titre XXIV",diff:2,expl:"L'<strong>entraide</strong> s'appuie sur la convention d'application de Schengen et instruments UE."},
  {id:'eu05',cat:'EUROP',q:"La transmission d'une commission rogatoire internationale à un État membre se fait :",opts:["Par courrier simple","Par les canaux centralisés (ministère de la Justice / Eurojust selon les cas)","Par le suspect","Par WhatsApp"],c:1,art:"Art. 694-1 CPP",diff:2,expl:"Les <strong>commissions rogatoires internationales</strong> transitent par les autorités centrales."},
  {id:'eu06',cat:'EUROP',q:"Le principe de reconnaissance mutuelle des décisions pénales UE concerne notamment :",opts:["Les contraventions de stationnement","Les décisions de gel et confiscation, les peines sous certaines conditions","Les mariages","Les impôts"],c:1,art:"Droit UE",diff:3,expl:"Le <strong>gel des avoirs</strong> et certaines peines font l'objet de reconnaissance mutuelle."},
  {id:'eu07',cat:'EUROP',q:"Le MAE remplace pour les États Schengen :",opts:["Toute extradition","L'extradition classique entre États membres pour les infractions couvertes","L'audition libre","La GAV"],c:1,art:"Décision-cadre MAE",diff:2,expl:"Le <strong>MAE</strong> est un système d'extradition simplifié intracommunautaire."},
  {id:'eu08',cat:'EUROP',q:"Les motifs de refus de exécution d'un MAE incluent :",opts:["Aucun","Amnistie, ne bis in idem, minorité selon les cas","La couleur des yeux","Le budget"],c:1,art:"Art. 695-22 CPP",diff:3,expl:"Des <strong>motifs facultatifs et obligatoires</strong> de non-exécution sont prévus (art. 695-22 s.)."},
  {id:'eu09',cat:'EUROP',q:"Eurojust peut :",opts:["Remplacer un tribunal","Coordonner les enquêtes transfrontalières entre États membres","Arrêter des suspects","Donner des peines"],c:1,art:"Règlement Eurojust",diff:2,expl:"<strong>Eurojust</strong> coordonne les enquêtes et poursuites transfrontalières."},
  {id:'eu10',cat:'EUROP',q:"La lettre rogatoire européenne pour obtenir des preuves est :",opts:["Interdite","LREL (directive 2014/41/UE transposée)","Uniquement papier","Réservée au civil"],c:1,art:"CPP mod. D. 2014/41/UE",diff:3,expl:"La <strong>lettre rogatoire européenne</strong> permet de demander des mesures d'enquête dans un autre État membre."},
  {id:'eu11',cat:'EUROP',q:"L'extradition hors UE est régie par :",opts:["Le MAE","Conventions bilatérales et loi d'extradition","Schengen seul","Le préfet"],c:1,art:"Loi d'extradition",diff:2,expl:"Hors UE, l'<strong>extradition</strong> relève des conventions internationales."},
  {id:'eu12',cat:'EUROP',q:"Le mandat d'arrêt national (MAN) diffère du MAE par :",opts:["Rien","Son champ (national vs européen)","Le prix","La durée de validité uniquement"],c:1,art:"CPP",diff:2,expl:"Le <strong>MAN</strong> est pour la fuite sur le territoire national ; le MAE est international intracommunautaire."},
  {id:'eu13',cat:'EUROP',q:"La notification d'une condamnation pénale à un autre État pour exécution de peine :",opts:["N'existe pas","Peut être faite selon les conventions de transfèrement des condamnés","Est automatique sans contrôle","Par le suspect"],c:1,art:"Convention européenne sur l'exécution des peines",diff:3,expl:"Le <strong>transfèrement de condamnés</strong> permet d'exécuter la peine dans l'État de résidence."},
  /* PROBATION */
  {id:'prob01',cat:'PROBATION',q:"Le sursis avec mise à l'épreuve est prévu à :",opts:["Art. 132-35 CP","Art. 132-40 CP","Art. 131-8 CP","Art. 721 CP"],c:1,art:"Art. 132-40 CP",diff:1,expl:"Le <strong>sursis probatoire</strong> est encadré par l'art. 132-40 CP."},
  {id:'prob02',cat:'PROBATION',q:"Le travail d'intérêt général (TIG) peut être prononcé comme :",opts:["Peine principale","Peine complémentaire ou obligation de peine selon les textes (131-8-1)","Contravention","Mesure civile"],c:1,art:"Art. 131-8-1 CP",diff:2,expl:"Le <strong>TIG</strong> est une peine complémentaire ou une obligation liée au sursis."},
  {id:'prob03',cat:'PROBATION',q:"L'ajournement du prononcé de la peine peut être ordonné pour :",opts:["Tous les crimes","Certains délits dans les conditions du code (132-41)","Les contraventions uniquement","Sans jamais de contrôle"],c:1,art:"Art. 132-41 CP",diff:2,expl:"L'<strong>ajournement</strong> permet de différer le prononcé sous mesures de réparation."},
  {id:'prob04',cat:'PROBATION',q:"La libération conditionnelle peut être accordée après :",opts:["1 jour de détention","Une fraction de la peine exécutée selon les règles (art. 729 C. pénitentiaire)","Avant tout jugement","Automatiquement à la sortie"],c:1,art:"Art. 729 C. pénitentiaire",diff:2,expl:"La <strong>libération conditionnelle</strong> est subordonnée à des conditions de détention et de bonne conduite."},
  {id:'prob05',cat:'PROBATION',q:"Le sursis simple (sans probatoire) est prévu à :",opts:["132-40 CP","132-34 CP","132-41 CP","434-1 CP"],c:1,art:"Art. 132-34 CP",diff:2,expl:"Le <strong>sursis simple</strong> diffère du sursis avec mise à l'épreuve (132-40)."},
  {id:'prob06',cat:'PROBATION',q:"En cas de violation du sursis probatoire :",opts:["Rien","Le juge peut révoquer le sursis et prononcer la peine","Amende forfaitaire","Classement sans suite"],c:1,art:"Art. 132-40 CP",diff:2,expl:"La <strong>révocation</strong> du sursis probatoire entraîne le prononcé de la peine encourue."},
  {id:'prob07',cat:'PROBATION',q:"Le bracelet électronique peut accompagner :",opts:["Uniquement les violences","Le contrôle judiciaire ou la libération sous contrainte selon les textes","Les contraventions","Uniquement les mineurs"],c:1,art:"CPP / exécution des peines",diff:2,expl:"Le <strong>bracelet</strong> est une mesure de contrôle électronique."},
  {id:'prob08',cat:'PROBATION',q:"Le jour-amende peut être combiné avec :",opts:["Jamais le sursis","Le sursis selon les conditions légales","La perpétuité","L'immunité diplomatique"],c:1,art:"Art. 131-8 CP",diff:3,expl:"Le <strong>jour-amende</strong> est une peine pécuniaire encadrée."},
  {id:'prob09',cat:'PROBATION',q:"La mesure de réparation imposée en ajournement peut être :",opts:["Aucune","Dommages et intérêts, soins, travail selon 132-41","Prison immédiate","Peine de mort"],c:1,art:"Art. 132-41 CP",diff:2,expl:"L'<strong>ajournement</strong> impose souvent des mesures de réparation."},
  {id:'prob10',cat:'PROBATION',q:"La contrainte pénale (remplace courtes peines d'emprisonnement) peut inclure :",opts:["TIG, stage de citoyenneté, etc.","Perpétuité","Exil","Interdiction de vote à vie"],c:0,art:"Art. 131-8-1 CP",diff:2,expl:"La <strong>contrainte pénale</strong> regroupe des obligations alternatives à la courte détention."},
  {id:'prob11',cat:'PROBATION',q:"La semi-liberté est une mesure :",opts:["Civile","D'exécution de la peine permettant le travail à l'extérieur","Disciplinaire interne","Réservée aux fonctionnaires"],c:1,art:"Art. 723-5 C. pénitentiaire",diff:2,expl:"La <strong>semi-liberté</strong> permet un aménagement de la détention."},
  {id:'prob12',cat:'PROBATION',q:"Le placement à l'extérieur (PEX) nécessite :",opts:["Aucune condition","Un avis favorable et des garanties de représentation","L'accord du préfet seul","Un mandat d'arrêt"],c:1,art:"C. pénitentiaire",diff:3,expl:"Le <strong>PEX</strong> est encadré par l'administration pénitentiaire."},
  {id:'prob13',cat:'PROBATION',q:"Le sursis avec obligation de soins relève de :",opts:["132-34 CP","132-40 CP — obligations sous contrôle du juge de l'application","434-1 CP","Rien"],c:1,art:"Art. 132-40 CP",diff:2,expl:"Le sursis probatoire peut imposer des <strong>soins</strong> (addiction, psychiatrie)."},
  {id:'prob14',cat:'PROBATION',q:"La réduction de peine pour bonne conduite (CRP) :",opts:["N'existe pas","Réduit la durée de détention selon les règles (art. 720 et s. C. pénitentiaire)","Est automatique à 50 %","Est réservée aux crimes"],c:1,art:"Art. 720 C. pénitentiaire",diff:2,expl:"Les <strong>réductions de peine</strong> sont mécaniques dans le cadre légal."},
  {id:'prob15',cat:'PROBATION',q:"L'exécution du suspensif de la peine (appel) :",opts:["Suspend toujours l'exécution","Peut suspendre l'exécution selon les conditions (CPP)","N'existe pas","Est réservée au civil"],c:1,art:"Art. 515 CPP",diff:3,expl:"Le <strong>suspensif</strong> permet de ne pas exécuter la peine en attendant l'appel sous conditions."},
  /* ── FLAGRANCE (8 nouvelles) ── */
  {id:'f04',cat:'FLAGRANCE',q:"L'article 53 CPP définit le crime ou délit flagrant comme :",opts:["Commis depuis moins de 48h","Qui se commet ou vient de se commettre dans un temps très voisin de l'action","Constaté uniquement par un OPJ","Ayant fait l'objet d'une plainte"],c:1,art:"Art. 53 CPP",diff:1,expl:"L'art. 53 CPP vise le crime/délit <strong>qui se commet actuellement ou dans un temps très voisin de l'action</strong>."},
  {id:'f05',cat:'FLAGRANCE',q:"La prolongation de l'enquête de flagrance au-delà de 8 jours est autorisée par :",opts:["Le procureur de la République","Le juge des libertés et de la détention","Le préfet","Le juge d'instruction"],c:0,art:"Art. 53 CPP",diff:2,expl:"La prolongation de 8 jours supplémentaires est autorisée par le <strong>procureur de la République</strong> pour les délits punis d'au moins 5 ans."},
  {id:'f06',cat:'FLAGRANCE',q:"En flagrance, les horaires de perquisition (art. 59 CPP) sont :",opts:["Libres 24h/24","De 6h à 21h sauf exceptions légales","De 8h à 20h","Uniquement de nuit"],c:1,art:"Art. 59 CPP",diff:2,expl:"La règle générale est <strong>6h-21h</strong>. Des exceptions existent pour certains crimes (art. 706-89 et s.)."},
  {id:'f07',cat:'FLAGRANCE',q:"L'OPJ territorialement compétent en flagrance (art. 54 CPP) est :",opts:["Celui du domicile de l'auteur","Celui du lieu de constatation de l'infraction","N'importe quel OPJ de France","L'OPJ désigné par le PR"],c:1,art:"Art. 54 CPP",diff:2,expl:"L'OPJ compétent est celui du <strong>lieu de constatation</strong> de l'infraction flagrante."},
  {id:'f08',cat:'FLAGRANCE',q:"La clameur publique comme critère de flagrance (art. 53 al.2 CPP) signifie :",opts:["Un article de presse","La poursuite du suspect par la victime ou des témoins criant 'au voleur'","Une dénonciation anonyme","Un signalement par les RG"],c:1,art:"Art. 53 al.2 CPP",diff:2,expl:"La <strong>clameur publique</strong> est l'un des critères assimilés à la flagrance : la personne est poursuivie par la rumeur publique."},
  {id:'f09',cat:'FLAGRANCE',q:"Les 'indices apparents' comme critère de flagrance (art. 53 CPP) :",opts:["Supposent un aveu","Sont des traces ou objets laissant présumer la participation à un crime/délit","Nécessitent une expertise préalable","Ne concernent que les contraventions"],c:1,art:"Art. 53 CPP",diff:2,expl:"Les <strong>indices apparents</strong> (traces, objets, blessures) permettent de qualifier la flagrance même en l'absence de témoins directs."},
  {id:'f10',cat:'FLAGRANCE',q:"En flagrance par rapport à l'enquête préliminaire, l'OPJ dispose :",opts:["Des mêmes pouvoirs exactement","De pouvoirs de contrainte immédiate sans autorisation préalable du JLD","De moins de pouvoirs","Uniquement du pouvoir d'audition"],c:1,art:"Art. 53 à 74 CPP",diff:2,expl:"En flagrance, l'OPJ a des <strong>pouvoirs de contrainte immédiats</strong> (perquisition sans consentement, réquisitions) là où la préliminaire exige souvent l'accord du JLD."},
  {id:'f11',cat:'FLAGRANCE',q:"Lorsqu'un crime connexe est découvert lors d'une enquête de flagrance :",opts:["L'enquête doit être close","L'OPJ peut étendre ses investigations au crime connexe","Il faut une nouvelle saisine du PR","Seul le JI peut agir"],c:1,art:"Art. 53 CPP",diff:3,expl:"L'<strong>extension de flagrance</strong> permet à l'OPJ de couvrir les crimes/délits connexes découverts à l'occasion de l'enquête initiale."},
  /* ── COMMISSION ROGATOIRE (6 nouvelles) ── */
  {id:'cr03',cat:'COMMISSION',q:"Seul le juge d'instruction peut délivrer une commission rogatoire, pas :",opts:["Le JLD","Le procureur de la République","Le greffier","Les trois réponses ci-dessus"],c:1,art:"Art. 151 CPP",diff:1,expl:"La CR est un <strong>acte exclusif du JI</strong>. Le PR ne peut que requérir l'ouverture d'une information."},
  {id:'cr04',cat:'COMMISSION',q:"Sous commission rogatoire, l'OPJ bénéficie d'une compétence :",opts:["Limitée à son ressort","Nationale (art. 18 al.4 CPP)","Départementale","Communale"],c:1,art:"Art. 18 al.4 CPP",diff:2,expl:"En CR, l'OPJ a une <strong>compétence nationale</strong> étendue par l'art. 18 al.4 CPP."},
  {id:'cr05',cat:'COMMISSION',q:"L'exécution d'une commission rogatoire peut-elle être confiée à un APJ ?",opts:["Oui, sans restriction","Non, seul un OPJ peut être commis","Oui, sur autorisation du PR","Oui, pour les contraventions"],c:1,art:"Art. 151 CPP",diff:2,expl:"La CR ne peut être exécutée que par un <strong>OPJ</strong>. La subdélégation à un APJ est interdite."},
  {id:'cr06',cat:'COMMISSION',q:"L'OPJ agissant sous commission rogatoire ne peut pas :",opts:["Procéder à des perquisitions","Placer en garde à vue","Procéder à une mise en examen","Entendre des témoins"],c:2,art:"Art. 152 CPP",diff:2,expl:"La <strong>mise en examen</strong> est un acte personnel du JI qui ne peut être délégué par CR."},
  {id:'cr07',cat:'COMMISSION',q:"La durée d'une commission rogatoire est :",opts:["Toujours de 8 jours","Fixée par la commission rogatoire elle-même","Illimitée","De 4 mois renouvelables"],c:1,art:"Art. 151 CPP",diff:2,expl:"La <strong>durée de la CR</strong> est déterminée par le JI dans l'acte de commission lui-même."},
  {id:'cr08',cat:'COMMISSION',q:"La distinction principale entre CR et réquisition du PR est :",opts:["Aucune différence","La CR émane du JI (instruction), la réquisition du PR (enquête)","La CR est orale, la réquisition écrite","La CR est plus rapide"],c:1,art:"Art. 151 / Art. 77-1 CPP",diff:2,expl:"La <strong>CR émane du JI</strong> dans le cadre d'une information judiciaire, tandis que la réquisition émane du <strong>PR</strong> en enquête préliminaire ou flagrance."},
  /* ── PERQUISITIONS (6 nouvelles) ── */
  {id:'p05',cat:'PERQUIZ',q:"Les perquisitions de droit commun ne peuvent débuter qu'entre (art. 59 CPP) :",opts:["8h et 20h","6h et 21h, sauf exceptions pour les crimes de BO","7h et 22h","Aucune restriction horaire"],c:1,art:"Art. 59 CPP",diff:1,expl:"L'art. 59 CPP pose la règle <strong>6h-21h</strong>. Des exceptions permettent les perquisitions nocturnes en criminalité organisée."},
  {id:'p06',cat:'PERQUIZ',q:"Lorsque l'occupant est absent lors d'une perquisition, l'OPJ doit (art. 57 CPP) :",opts:["Reporter l'opération","Requérir 2 témoins étrangers aux services de police","Appeler le bâtonnier","Faire intervenir un huissier"],c:1,art:"Art. 57 CPP",diff:2,expl:"En l'absence de l'occupant, <strong>2 témoins</strong> (majeurs, non liés aux services) doivent assister à la perquisition."},
  {id:'p07',cat:'PERQUIZ',q:"La perquisition dans un cabinet d'avocat nécessite la présence obligatoire :",opts:["Du procureur général","Du bâtonnier ou de son délégué","Du juge de proximité","De l'avocat lui-même uniquement"],c:1,art:"Art. 56-1 CPP",diff:2,expl:"La <strong>présence du bâtonnier</strong> (ou son délégué) est impérative pour protéger le secret professionnel."},
  {id:'p08',cat:'PERQUIZ',q:"L'article 57-1 CPP relatif aux données numériques permet :",opts:["Uniquement la saisie du matériel","La consultation sur place et la copie des données informatiques","L'effacement des données","La revente du matériel"],c:1,art:"Art. 57-1 CPP",diff:2,expl:"L'art. 57-1 permet la <strong>consultation sur place et la copie</strong> des données stockées sur support numérique."},
  {id:'p09',cat:'PERQUIZ',q:"En enquête préliminaire, sans le consentement de l'occupant, la perquisition nécessite :",opts:["Une simple réquisition du PR","L'autorisation du JLD (art. 76 CPP)","L'accord du maire","Aucune autorisation"],c:1,art:"Art. 76 CPP",diff:2,expl:"Sans consentement écrit, la perquisition en préliminaire requiert l'<strong>autorisation du JLD</strong>."},
  {id:'p10',cat:'PERQUIZ',q:"Les perquisitions nocturnes (après 21h) sont possibles pour :",opts:["Tous les délits","Les crimes de bande organisée avec autorisation du JLD","Les contraventions uniquement","Uniquement en flagrance"],c:1,art:"Art. 706-89 à 706-94 CPP",diff:3,expl:"Les perquisitions nocturnes sont réservées à la <strong>criminalité organisée</strong>, avec autorisation motivée du JLD."},
  /* ── NULLITÉS (5 nouvelles) ── */
  {id:'n02',cat:'NULLITES',q:"La nullité textuelle (art. 171 CPP) est prononcée :",opts:["Uniquement si un grief est démontré","De plein droit dès qu'un texte la prévoit expressément","Seulement en appel","Par le PR"],c:1,art:"Art. 171 CPP",diff:2,expl:"La nullité textuelle est <strong>automatique</strong> : la seule violation du texte qui l'édicte suffit, sans démonstration de grief."},
  {id:'n03',cat:'NULLITES',q:"La nullité substantielle (art. 802 CPP) suppose la preuve :",opts:["D'une violation de texte uniquement","D'un grief effectif subi par la partie qui l'invoque","De la mauvaise foi de l'enquêteur","D'un vice de procédure irréparable"],c:1,art:"Art. 802 CPP",diff:2,expl:"L'art. 802 CPP pose le principe <strong>'pas de nullité sans grief'</strong> pour les nullités substantielles."},
  {id:'n04',cat:'NULLITES',q:"Le délai pour soulever une nullité de procédure est :",opts:["Illimité","Avant tout débat sur le fond (in limine litis)","30 jours après la clôture","Après le jugement uniquement"],c:1,art:"Art. 385 CPP",diff:2,expl:"Les nullités doivent être soulevées <strong>avant tout débat sur le fond</strong> (in limine litis), sous peine de forclusion."},
  {id:'n05',cat:'NULLITES',q:"La 'purge des nullités' signifie :",opts:["Que toutes les nullités sont pardonnées","Que le mis en examen, après mise en examen, a un délai de 6 mois pour les invoquer, passé lequel elles sont couvertes","Que le JI corrige lui-même les vices","Que le PR annule les actes"],c:1,art:"Art. 173-1 CPP",diff:3,expl:"La <strong>purge des nullités</strong> impose un délai (6 mois) pour les soulever en cours d'instruction, au-delà duquel elles sont irrecevables."},
  {id:'n06',cat:'NULLITES',q:"L'annulation d'un acte entraîne sur les actes subséquents :",opts:["Aucun effet","L'annulation de tous les actes qui en sont le support nécessaire","L'annulation de toute la procédure","Un simple avertissement"],c:1,art:"Art. 174 CPP",diff:3,expl:"L'annulation d'un acte emporte celle de <strong>tous les actes dont il est le support nécessaire</strong> (théorie du fruit de l'arbre empoisonné)."},

  /* ── OPJ (8 nouvelles) ── */
  {id:'o03',cat:'OPJ',q:"Les fonctionnaires pouvant être OPJ sont listés à :",opts:["Art. 14 CPP","Art. 16 CPP","Art. 20 CPP","Art. 21 CPP"],c:1,art:"Art. 16 CPP",diff:1,expl:"L'art. 16 CPP énumère limitativement les fonctionnaires pouvant avoir la qualité d'<strong>OPJ</strong>."},
  {id:'o04',cat:'OPJ',q:"L'OPJ exerce ses fonctions sous la direction :",opts:["Du préfet","Du procureur de la République","Du ministre de l'Intérieur","Du JLD"],c:1,art:"Art. 12 CPP",diff:1,expl:"L'OPJ agit sous la <strong>direction du procureur</strong> de la République (art. 12 CPP)."},
  {id:'o05',cat:'OPJ',q:"Le contrôle disciplinaire de l'OPJ est exercé par :",opts:["Le préfet","Le PR","La chambre de l'instruction de la cour d'appel","Le JLD"],c:2,art:"Art. 13 CPP",diff:2,expl:"La <strong>chambre de l'instruction</strong> exerce le contrôle disciplinaire et peut suspendre ou retirer l'habilitation OPJ."},
  {id:'o06',cat:'OPJ',q:"L'APJ (art. 20 CPP) peut-il placer en garde à vue ?",opts:["Oui librement","Non, seul l'OPJ le peut","Oui avec accord du PR","Oui en flagrance uniquement"],c:1,art:"Art. 20 CPP",diff:1,expl:"<strong>Seul l'OPJ</strong> peut placer en garde à vue. L'APJ rend compte à l'OPJ."},
  {id:'o07',cat:'OPJ',q:"L'habilitation OPJ peut être retirée par :",opts:["Le PR","Le procureur général","La chambre de l'instruction","Le ministre de l'Intérieur"],c:2,art:"Art. 16 CPP",diff:2,expl:"Le retrait de l'habilitation relève de la <strong>chambre de l'instruction</strong>."},
  {id:'o08',cat:'OPJ',q:"Le ressort de compétence normal d'un OPJ est :",opts:["National","Départemental ou zonal selon habilitation","Communal","Régional"],c:1,art:"Art. 18 CPP",diff:2,expl:"L'OPJ est compétent dans son <strong>ressort d'affectation</strong> (départemental ou zonal), sauf en CR (national)."},
  {id:'o09',cat:'OPJ',q:"L'APJA (art. 21 CPP) a pour mission de :",opts:["Diriger les enquêtes","Seconder les OPJ et APJ dans leurs fonctions","Placer en GAV les mineurs","Délivrer des mandats"],c:1,art:"Art. 21 CPP",diff:1,expl:"L'APJA <strong>seconde</strong> les OPJ et APJ. Il n'a aucun pouvoir coercitif propre."},
  {id:'o10',cat:'OPJ',q:"La notation de l'OPJ par le procureur général porte sur :",opts:["Sa productivité uniquement","Son aptitude à exercer les attributions de PJ","Sa politesse","Son ancienneté"],c:1,art:"Art. 19-1 CPP",diff:2,expl:"Le PG note l'OPJ sur son <strong>aptitude à exercer les attributions attachées à la qualité d'OPJ</strong>."},

  /* ── AUDLIB (8 nouvelles) ── */
  {id:'a03',cat:'AUDLIB',q:"En audition libre, le droit au silence doit être notifié :",opts:["Avant la première question","Uniquement si la personne le demande","Après 30 minutes","Jamais en audition libre"],c:0,art:"Art. 61-1 CPP",diff:1,expl:"Le droit au silence est notifié <strong>dès le début</strong> de l'audition libre."},
  {id:'a04',cat:'AUDLIB',q:"L'assistance d'un avocat en audition libre est obligatoire si :",opts:["Toujours","L'infraction est punie d'emprisonnement","La personne est mineure uniquement","Le PR l'ordonne"],c:1,art:"Art. 61-1 CPP",diff:2,expl:"L'avocat est de droit en AL si l'infraction est <strong>punie d'emprisonnement</strong>."},
  {id:'a05',cat:'AUDLIB',q:"La principale différence entre audition libre et GAV est :",opts:["La durée","La liberté de quitter les lieux à tout moment","Le lieu","Le nombre de policiers"],c:1,art:"Art. 61-1 CPP",diff:1,expl:"En AL, la personne peut <strong>quitter les lieux à tout moment</strong>. C'est le critère fondamental."},
  {id:'a06',cat:'AUDLIB',q:"En audition libre, la personne doit être informée de :",opts:["La qualification juridique des faits reprochés","Son horoscope","L'identité du juge","Le montant de l'amende forfaitaire"],c:0,art:"Art. 61-1 CPP",diff:2,expl:"La personne est informée de la <strong>qualification, date et lieu</strong> des faits reprochés."},
  {id:'a07',cat:'AUDLIB',q:"Un témoin entendu sous serment (art. 103 CPP) peut-il refuser de déposer ?",opts:["Oui librement","Non, sous peine d'amende (art. 109 CPP)","Seulement s'il est avocat","Oui si mineur"],c:1,art:"Art. 109 CPP",diff:2,expl:"Le témoin est <strong>tenu de déposer</strong> sous peine d'amende de 3 750 €."},
  {id:'a08',cat:'AUDLIB',q:"Une personne suspectée prête-t-elle serment ?",opts:["Oui toujours","Non jamais — seuls les témoins prêtent serment","Oui en flagrance","Seulement devant le JI"],c:1,art:"Art. 105 CPP",diff:1,expl:"<strong>Jamais</strong> de serment pour un suspect. Prêter serment un suspect est une cause de nullité."},
  {id:'a09',cat:'AUDLIB',q:"L'audition libre peut-elle basculer en garde à vue ?",opts:["Non jamais","Oui si les conditions de la GAV sont réunies en cours d'audition","Seulement avec accord du JLD","Oui après 4 heures automatiquement"],c:1,art:"Art. 61-1 / Art. 62-2 CPP",diff:2,expl:"Si les conditions de la GAV apparaissent, l'OPJ peut <strong>basculer en GAV</strong> à tout moment."},
  {id:'a10',cat:'AUDLIB',q:"La durée maximale d'une audition libre est :",opts:["4 heures","8 heures","24 heures","Aucune durée maximale légale fixée"],c:3,art:"Art. 61-1 CPP",diff:2,expl:"L'AL n'a <strong>pas de durée maximale légale</strong>, mais la personne peut partir à tout moment."},

  /* ── LEGDEF (8 nouvelles) ── */
  {id:'ld03',cat:'LEGDEF',q:"La légitime défense des biens est prévue à :",opts:["Art. 122-5 al.1 CP","Art. 122-5 al.2 CP","Art. 122-7 CP","Art. 122-1 CP"],c:1,art:"Art. 122-5 al.2 CP",diff:2,expl:"La LD des <strong>biens</strong> est prévue à l'al. 2 de l'art. 122-5 CP, avec des conditions plus strictes."},
  {id:'ld04',cat:'LEGDEF',q:"En légitime défense, la riposte doit être :",opts:["Supérieure à l'attaque","Proportionnée à la gravité de l'atteinte","Identique en tous points","Décidée par le PR"],c:1,art:"Art. 122-5 CP",diff:1,expl:"La riposte doit être <strong>proportionnée</strong> à la gravité de l'atteinte."},
  {id:'ld05',cat:'LEGDEF',q:"La présomption de légitime défense (art. 122-6 CP) s'applique :",opts:["À toute agression","En cas d'intrusion nocturne par effraction dans un lieu habité","Uniquement pour les forces de l'ordre","Jamais"],c:1,art:"Art. 122-6 CP",diff:2,expl:"L'art. 122-6 crée une <strong>présomption</strong> de LD en cas d'intrusion nocturne par bris, effraction ou escalade."},
  {id:'ld06',cat:'LEGDEF',q:"La légitime défense exclut un homicide pour protéger :",opts:["Des personnes","Des biens uniquement (sauf cas exceptionnels)","L'honneur","La propriété intellectuelle"],c:1,art:"Art. 122-5 al.2 CP",diff:2,expl:"La LD des biens exclut l'homicide volontaire sauf disproportion exceptionnelle."},
  {id:'ld07',cat:'LEGDEF',q:"L'état de nécessité (art. 122-7 CP) se distingue de la LD par :",opts:["Rien","L'absence d'agression humaine nécessaire","Le lieu","Le moment de la journée"],c:1,art:"Art. 122-7 CP",diff:2,expl:"L'<strong>état de nécessité</strong> ne suppose pas d'agression humaine : un danger actuel ou imminent suffit."},
  {id:'ld08',cat:'LEGDEF',q:"La contrainte irrésistible (art. 122-2 CP) est :",opts:["Une excuse atténuante","Une cause d'irresponsabilité pénale supprimant l'infraction","Un fait aggravant","Un motif de réduction de peine"],c:1,art:"Art. 122-2 CP",diff:2,expl:"La contrainte irrésistible est une <strong>cause d'irresponsabilité</strong> qui supprime la culpabilité."},
  {id:'ld09',cat:'LEGDEF',q:"L'ordre de la loi ou le commandement légitime (art. 122-4 CP) exonère :",opts:["Jamais","Si l'acte est prescrit par la loi ou ordonné par l'autorité légitime","Seulement les militaires","Seulement en temps de guerre"],c:1,art:"Art. 122-4 CP",diff:2,expl:"L'art. 122-4 exonère celui qui accomplit un acte <strong>prescrit ou autorisé</strong> par des dispositions législatives ou réglementaires."},
  {id:'ld10',cat:'LEGDEF',q:"Un policier qui use de son arme sans nécessité peut invoquer la légitime défense :",opts:["Oui toujours","Non si la riposte est disproportionnée","Oui car il est PDAP","Seulement en CO"],c:1,art:"Art. 122-5 CP / Art. L435-1 CSI",diff:3,expl:"La LD ne couvre pas une riposte <strong>disproportionnée</strong>, même pour un policier."},

  /* ── RECIDIVE (8 nouvelles) ── */
  {id:'r03',cat:'RECIDIVE',q:"La récidive légale exige une condamnation :",opts:["Simple","Définitive et irrévocable","En première instance suffit","Prononcée par le PR"],c:1,art:"Art. 132-8 CP",diff:1,expl:"La récidive nécessite une <strong>condamnation définitive</strong> antérieure (plus de voie de recours)."},
  {id:'r04',cat:'RECIDIVE',q:"En récidive crime sur crime, le délai est :",opts:["5 ans","10 ans","Perpétuel (aucun délai)","3 ans"],c:2,art:"Art. 132-8 CP",diff:2,expl:"La récidive crime/crime est <strong>perpétuelle</strong> : aucun délai entre les deux condamnations."},
  {id:'r05',cat:'RECIDIVE',q:"En récidive délit sur délit, le délai est de :",opts:["3 ans","5 ans","10 ans","Perpétuel"],c:1,art:"Art. 132-10 CP",diff:2,expl:"Le délai de récidive pour les <strong>délits identiques ou assimilés</strong> est de 5 ans."},
  {id:'r06',cat:'RECIDIVE',q:"L'effet principal de la récidive légale sur la peine est :",opts:["Aucun effet","Le doublement du maximum de la peine encourue","La peine minimale obligatoire","L'interdiction de sursis"],c:1,art:"Art. 132-9 CP",diff:1,expl:"La récidive entraîne le <strong>doublement</strong> du maximum de la peine d'emprisonnement et d'amende."},
  {id:'r07',cat:'RECIDIVE',q:"La récidive spéciale concerne les infractions :",opts:["Toutes sans distinction","Identiques ou assimilées par le Code pénal","Uniquement les crimes","Uniquement les contraventions"],c:1,art:"Art. 132-10 CP",diff:2,expl:"La récidive spéciale vise des infractions <strong>identiques ou assimilées</strong> (ex: vol/extorsion)."},
  {id:'r08',cat:'RECIDIVE',q:"La composition pénale (art. 41-2 CPP) est proposée par :",opts:["Le JI","Le procureur de la République","Le JLD","L'OPJ"],c:1,art:"Art. 41-2 CPP",diff:2,expl:"La composition pénale est proposée par le <strong>PR</strong> et homologuée par le juge."},
  {id:'r09',cat:'RECIDIVE',q:"La CRPC (comparution sur reconnaissance préalable de culpabilité) est impossible pour :",opts:["Les délits","Les crimes et pour les mineurs","Les contraventions uniquement","Les délits routiers"],c:1,art:"Art. 495-7 CPP",diff:2,expl:"La CRPC est <strong>exclue pour les crimes et les mineurs</strong>."},
  {id:'r10',cat:'RECIDIVE',q:"Le rappel à la loi (art. 41-1 CPP) est :",opts:["Une peine","Une alternative aux poursuites décidée par le PR","Un mandat","Un acte d'instruction"],c:1,art:"Art. 41-1 CPP",diff:1,expl:"Le rappel à la loi est une <strong>alternative aux poursuites</strong> prise par le procureur."},

  /* ── TAJ (8 nouvelles) ── */
  {id:'t03',cat:'TAJ',q:"Le FAED (Fichier Automatisé des Empreintes Digitales) contient :",opts:["Les profils ADN","Les empreintes digitales et palmaires","Les antécédents judiciaires","Les photos signalétiques"],c:1,art:"Décret 87-249",diff:1,expl:"Le FAED contient les <strong>empreintes digitales et palmaires</strong>."},
  {id:'t04',cat:'TAJ',q:"Le FPR (Fichier des Personnes Recherchées) sert à :",opts:["Stocker les profils ADN","Signaler les personnes faisant l'objet d'une mesure de recherche","Enregistrer les contraventions","Archiver les PV"],c:1,art:"CSI",diff:1,expl:"Le FPR <strong>signale les personnes recherchées</strong> (mandats, disparitions, interdictions)."},
  {id:'t05',cat:'TAJ',q:"Le FIJAISV concerne :",opts:["Les infractions routières","Les auteurs d'infractions sexuelles ou violentes","Les étrangers en situation irrégulière","Les comptes bancaires"],c:1,art:"Art. 706-53-1 CPP",diff:2,expl:"Le FIJAISV recense les <strong>auteurs d'infractions sexuelles ou violentes</strong>."},
  {id:'t06',cat:'TAJ',q:"FICOBA permet à l'OPJ de connaître :",opts:["L'état civil complet","Les comptes bancaires ouverts au nom d'une personne","Le patrimoine immobilier","Les véhicules immatriculés"],c:1,art:"Livre des procédures fiscales",diff:2,expl:"FICOBA recense les <strong>comptes bancaires</strong> ouverts en France."},
  {id:'t07',cat:'TAJ',q:"Le refus de prélèvement ADN (FNAEG) constitue :",opts:["Une contravention","Un délit puni d'un an d'emprisonnement","Un crime","Aucune infraction"],c:1,art:"Art. 706-56 CPP",diff:2,expl:"Le refus de prélèvement ADN est un <strong>délit</strong> puni d'un an et 15 000 €."},
  {id:'t08',cat:'TAJ',q:"L'accès au TAJ est réservé aux :",opts:["Tous les policiers sans restriction","OPJ et APJ individuellement habilités","Citoyens sur demande","Journalistes accrédités"],c:1,art:"Décret 2012-652",diff:2,expl:"Seuls les <strong>OPJ et APJ individuellement habilités</strong> peuvent consulter le TAJ."},
  {id:'t09',cat:'TAJ',q:"La durée de conservation des données dans le TAJ pour un mis en cause majeur est de :",opts:["5 ans","20 ans maximum","40 ans maximum selon l'infraction","Illimitée"],c:2,art:"Décret 2012-652",diff:3,expl:"La conservation dans le TAJ peut aller jusqu'à <strong>40 ans</strong> pour les infractions les plus graves."},
  {id:'t10',cat:'TAJ',q:"Le SIS II (Système d'Information Schengen) permet :",opts:["De stocker les empreintes","De signaler des personnes et objets recherchés dans l'espace Schengen","De géolocaliser en temps réel","De mettre sur écoute"],c:1,art:"Règlement UE 1987/2006",diff:2,expl:"Le SIS II est le <strong>système de signalement européen</strong> dans l'espace Schengen."},

  /* ── PATRIMONIAL (7 nouvelles) ── */
  {id:'pat04',cat:'PATRIMONIAL',q:"L'AGRASC (Agence de gestion et de recouvrement des avoirs saisis et confisqués) :",opts:["Remplace l'OPJ dans les saisies","Gère les biens saisis ou confisqués dans le cadre pénal","Est un service du Trésor","N'existe qu'au niveau européen"],c:1,art:"Loi 2010-768",diff:2,expl:"L'AGRASC <strong>gère les avoirs saisis et confisqués</strong> pour le compte de la justice."},
  {id:'pat05',cat:'PATRIMONIAL',q:"La saisie pénale spéciale (art. 706-141 CPP) est autorisée par :",opts:["L'OPJ seul","Le JLD ou le JI","Le PR uniquement","Le préfet"],c:1,art:"Art. 706-141 CPP",diff:2,expl:"La saisie pénale spéciale est autorisée par le <strong>JLD ou le JI</strong>."},
  {id:'pat06',cat:'PATRIMONIAL',q:"Le blanchiment aggravé en bande organisée est puni de :",opts:["5 ans / 375k€","10 ans / 750 000 €","15 ans RC","Perpétuité"],c:1,art:"Art. 324-2 CP",diff:2,expl:"Le blanchiment aggravé en BO est puni de <strong>10 ans et 750 000 €</strong>."},
  {id:'pat07',cat:'PATRIMONIAL',q:"La non-justification de ressources (art. 321-6 CP) concerne :",opts:["Tout citoyen","Une personne en relation habituelle avec un auteur de crimes/délits","Les fonctionnaires uniquement","Les étrangers"],c:1,art:"Art. 321-6 CP",diff:3,expl:"L'art. 321-6 vise les personnes en <strong>relation habituelle</strong> avec des auteurs d'infractions."},
  {id:'pat08',cat:'PATRIMONIAL',q:"Les réquisitions bancaires par l'OPJ en enquête préliminaire nécessitent :",opts:["Aucune autorisation","L'autorisation du PR (art. 77-1-1 CPP)","L'autorisation du JLD","L'accord de la banque"],c:1,art:"Art. 77-1-1 CPP",diff:2,expl:"En préliminaire, les réquisitions bancaires nécessitent l'<strong>autorisation du PR</strong>."},
  {id:'pat09',cat:'PATRIMONIAL',q:"La confiscation obligatoire (art. 131-21 al.8 CP) s'applique à :",opts:["Tous les biens","Les instruments et produits de l'infraction (armes, stupéfiants)","Les voitures uniquement","Les comptes bancaires"],c:1,art:"Art. 131-21 al.8 CP",diff:2,expl:"Certains biens font l'objet d'une <strong>confiscation obligatoire</strong> (armes, stupéfiants)."},
  {id:'pat10',cat:'PATRIMONIAL',q:"L'enquête patrimoniale est menée par :",opts:["Le JLD","L'OPJ sous la direction du PR ou du JI","Le comptable public","L'huissier"],c:1,art:"Art. 706-141 CPP",diff:1,expl:"L'enquête patrimoniale est menée par l'<strong>OPJ</strong> sous la direction du PR ou du JI."},

  /* ── PRESCRIP (6 nouvelles) ── */
  {id:'pr05',cat:'PRESCRIP',q:"La prescription d'une contravention est de :",opts:["6 mois","1 an","3 ans","5 ans"],c:1,art:"Art. 9 CPP",diff:1,expl:"Les contraventions se prescrivent par <strong>1 an</strong>."},
  {id:'pr06',cat:'PRESCRIP',q:"Un acte d'instruction ou de poursuite interrompt la prescription, ce qui signifie :",opts:["Le délai est suspendu","Le délai repart intégralement à zéro","La prescription est définitivement acquise","Le délai est réduit de moitié"],c:1,art:"Art. 9-2 CPP",diff:2,expl:"L'interruption <strong>fait repartir le délai à zéro</strong> depuis l'acte interruptif."},
  {id:'pr07',cat:'PRESCRIP',q:"La suspension de la prescription :",opts:["Remet le compteur à zéro","Gèle le délai qui reprend là où il s'était arrêté","N'existe pas en droit français","Ne concerne que les crimes"],c:1,art:"Art. 9-3 CPP",diff:2,expl:"La suspension <strong>arrête le cours du délai</strong> sans l'effacer, puis il reprend."},
  {id:'pr08',cat:'PRESCRIP',q:"La prescription des crimes sexuels sur mineur commence à courir :",opts:["Au jour des faits","À la majorité de la victime","Au jour de la plainte","À la découverte des faits"],c:1,art:"Art. 7 al.3 CPP",diff:2,expl:"Pour les crimes sexuels sur mineurs, le délai court à partir de la <strong>majorité</strong> de la victime."},
  {id:'pr09',cat:'PRESCRIP',q:"Le crime d'abus de biens sociaux se prescrit par :",opts:["3 ans","6 ans depuis la loi 2017","12 ans maximum","20 ans"],c:1,art:"Art. 8 CPP",diff:3,expl:"L'ABS se prescrit par <strong>6 ans</strong> (loi 2017), report du point de départ possible en cas de dissimulation."},
  {id:'pr10',cat:'PRESCRIP',q:"La prescription de la peine diffère de la prescription de l'action publique en ce que :",opts:["Elles sont identiques","La prescription de la peine empêche l'exécution d'une peine prononcée","La prescription de la peine efface l'infraction","Elle n'existe pas"],c:1,art:"Art. 133-2 CP",diff:2,expl:"La prescription de la <strong>peine</strong> empêche l'exécution, tandis que celle de l'action publique empêche les poursuites."},

  /* ── REQS (10 nouvelles) ── */
  {id:'rq01',cat:'REQS',q:"Les réquisitions de l'OPJ en flagrance sont fondées sur :",opts:["Art. 60 CPP","Art. 77-1 CPP","Art. 76 CPP","Art. 100 CPP"],c:0,art:"Art. 60 CPP",diff:1,expl:"En flagrance, les réquisitions sont fondées sur l'<strong>art. 60 CPP</strong>."},
  {id:'rq02',cat:'REQS',q:"Les réquisitions en enquête préliminaire sont fondées sur :",opts:["Art. 60 CPP","Art. 77-1 CPP","Art. 56 CPP","Art. 100 CPP"],c:1,art:"Art. 77-1 CPP",diff:1,expl:"En préliminaire, les réquisitions relèvent de l'<strong>art. 77-1 CPP</strong>."},
  {id:'rq03',cat:'REQS',q:"L'OPJ peut requérir un médecin légiste sur le fondement de :",opts:["Art. 60 CPP en flagrance ou art. 77-1 en préliminaire","Art. 100 CPP","Art. 56 CPP","Aucun texte"],c:0,art:"Art. 60 / 77-1 CPP",diff:2,expl:"Le médecin légiste est réquisitionné sur le fondement de l'<strong>art. 60 (flagrance) ou 77-1 (préliminaire)</strong>."},
  {id:'rq04',cat:'REQS',q:"Les réquisitions aux opérateurs téléphoniques pour les fadettes sont possibles :",opts:["Sans aucune autorisation","Sur autorisation du PR (art. 77-1-1 CPP) en préliminaire","Uniquement en instruction","Seulement avec le consentement de l'abonné"],c:1,art:"Art. 77-1-1 CPP",diff:2,expl:"En préliminaire, les réquisitions téléphoniques nécessitent l'<strong>autorisation du PR</strong>."},
  {id:'rq05',cat:'REQS',q:"Le refus de déférer à une réquisition de l'OPJ est puni de :",opts:["Rien","Une amende de 3 750 € (art. 60-2 CPP)","5 ans de prison","Une contravention de 1re classe"],c:1,art:"Art. 60-2 CPP",diff:2,expl:"Le refus de réquisition est puni d'une <strong>amende de 3 750 €</strong>."},
  {id:'rq06',cat:'REQS',q:"En flagrance, l'OPJ peut requérir toute personne qualifiée :",opts:["Sans autorisation préalable","Avec autorisation du PR","Avec autorisation du JI","Avec accord de la personne uniquement"],c:0,art:"Art. 60 CPP",diff:1,expl:"En flagrance, l'OPJ requiert <strong>sans autorisation</strong> préalable toute personne qualifiée."},
  {id:'rq07',cat:'REQS',q:"La réquisition à personne qualifiée permet notamment :",opts:["De placer en GAV","De procéder à des examens techniques ou scientifiques","De délivrer un mandat","D'écouter les communications"],c:1,art:"Art. 60 CPP",diff:1,expl:"Les réquisitions permettent des <strong>examens techniques ou scientifiques</strong> (analyses, expertises)."},
  {id:'rq08',cat:'REQS',q:"La distinction entre réquisition (OPJ) et expertise (JI) est :",opts:["Aucune","La réquisition est un acte d'enquête, l'expertise est un acte d'instruction contradictoire","La réquisition est plus longue","L'expertise est réservée aux APJ"],c:1,art:"Art. 60 / Art. 156 CPP",diff:2,expl:"La <strong>réquisition</strong> est un acte d'enquête (OPJ) ; l'<strong>expertise</strong> est un acte d'instruction (JI) avec débat contradictoire."},
  {id:'rq09',cat:'REQS',q:"Les réquisitions aux administrations (fisc, CAF, Sécu) en préliminaire nécessitent :",opts:["Aucune autorisation","L'autorisation du PR (art. 77-1-1 CPP)","L'autorisation du JLD","Un mandat du JI"],c:1,art:"Art. 77-1-1 CPP",diff:2,expl:"En préliminaire, l'autorisation du <strong>PR</strong> est nécessaire pour les réquisitions administratives."},
  {id:'rq10',cat:'REQS',q:"L'OPJ peut-il requérir un serrurier pour ouvrir un local en flagrance ?",opts:["Non jamais","Oui sur le fondement de l'art. 60 CPP","Seulement avec accord du PR","Seulement avec accord du JLD"],c:1,art:"Art. 60 CPP",diff:2,expl:"En flagrance, l'OPJ peut requérir tout professionnel nécessaire, y compris un <strong>serrurier</strong> (art. 60 CPP)."},

  /* ── ALTERNATIVES (alt03–alt10) ── */
  {id:'alt03',cat:'ALTERNATIVES',q:"La médiation pénale (art. 41-1 CPP) est proposée par :",opts:["Le juge d'instruction","Le procureur de la République","L'OPJ","La victime"],c:1,art:"Art. 41-1 CPP",diff:1,expl:"La médiation pénale est une mesure alternative proposée par le <strong>procureur de la République</strong> avec l'accord des parties."},
  {id:'alt04',cat:'ALTERNATIVES',q:"La CRPC (art. 495-7 CPP) est exclue pour :",opts:["Les délits routiers","Les crimes et les mineurs","Les délits punis de moins de 2 ans","Les délits de presse uniquement"],c:1,art:"Art. 495-7 CPP",diff:2,expl:"La CRPC est <strong>exclue pour les crimes et les mineurs</strong>. Elle concerne uniquement les délits reconnus par un majeur."},
  {id:'alt05',cat:'ALTERNATIVES',q:"L'avertissement pénal probatoire (ex-rappel à la loi) est prévu à :",opts:["Art. 41-1 CPP","Art. 41-2 CPP","Art. 495-7 CPP","Art. 44-1 CPP"],c:0,art:"Art. 41-1 CPP",diff:1,expl:"L'avertissement pénal probatoire, qui remplace le rappel à la loi depuis la loi du 22 décembre 2021, est prévu à l'<strong>art. 41-1 CPP</strong>."},
  {id:'alt06',cat:'ALTERNATIVES',q:"La transaction par OPJ (art. 44-1 CPP) concerne :",opts:["Tous les délits","Certaines contraventions et certains délits limitativement énumérés","Les crimes uniquement","Les infractions de terrorisme"],c:1,art:"Art. 44-1 CPP",diff:2,expl:"La transaction par OPJ concerne <strong>certaines contraventions et délits limitativement énumérés</strong> (usage de stupéfiants, vol simple, etc.) avec accord du PR."},
  {id:'alt07',cat:'ALTERNATIVES',q:"L'ordonnance pénale (art. 495 CPP) permet de statuer :",opts:["Après un débat contradictoire","Sans audience, sur dossier uniquement","Après une mise en examen","Sur commission rogatoire"],c:1,art:"Art. 495 CPP",diff:2,expl:"L'ordonnance pénale permet au juge de statuer <strong>sans audience, sur le seul dossier</strong>. Le prévenu peut former opposition dans les 30 jours."},
  {id:'alt08',cat:'ALTERNATIVES',q:"L'amende forfaitaire délictuelle (art. 495-17 CPP) est applicable notamment à :",opts:["Tous les délits","L'usage de stupéfiants et certains délits limitativement prévus","Les crimes","Les contraventions exclusivement"],c:1,art:"Art. 495-17 CPP",diff:2,expl:"L'AFD s'applique à <strong>l'usage de stupéfiants, la conduite sans permis, la conduite sans assurance</strong> et d'autres délits limitativement prévus."},
  {id:'alt09',cat:'ALTERNATIVES',q:"Depuis la loi du 23 mars 2019, la peine d'emprisonnement proposée en CRPC ne peut excéder :",opts:["1 an","2 ans","3 ans","5 ans"],c:2,art:"Art. 495-8 CPP",diff:3,expl:"Depuis la loi du 23 mars 2019, la peine d'emprisonnement en CRPC ne peut excéder <strong>3 ans</strong> (auparavant 1 an)."},
  {id:'alt10',cat:'ALTERNATIVES',q:"La composition pénale doit être validée par :",opts:["Le procureur de la République","Le président du tribunal judiciaire par ordonnance","Le JLD","Le juge d'instruction"],c:1,art:"Art. 41-2 CPP",diff:2,expl:"La composition pénale proposée par le PR doit être <strong>validée par ordonnance du président du tribunal judiciaire</strong>."},

  /* ── CDO (cdo04–cdo10) ── */
  {id:'cdo04',cat:'CDO',q:"En cas de découverte d'un cadavre, l'OPJ doit en premier lieu :",opts:["Qualifier l'infraction","Informer immédiatement le procureur de la République","Placer les témoins en GAV","Procéder à l'autopsie"],c:1,art:"Art. 74 CPP",diff:1,expl:"L'OPJ doit <strong>informer immédiatement le procureur</strong> en cas de découverte d'un cadavre dont la cause de mort est inconnue ou suspecte."},
  {id:'cdo05',cat:'CDO',q:"L'article 74 CPP s'applique lorsque la cause de la mort est :",opts:["Certaine et naturelle","Inconnue ou suspecte","Uniquement criminelle","Uniquement accidentelle"],c:1,art:"Art. 74 CPP",diff:1,expl:"L'art. 74 s'applique lorsque la cause de la mort est <strong>inconnue ou suspecte</strong>, avant toute qualification pénale."},
  {id:'cdo06',cat:'CDO',q:"Le médecin légiste requis sur le fondement de l'art. 74 CPP a pour mission :",opts:["De procéder à l'autopsie complète","D'effectuer un examen externe du corps et donner un avis sur la cause du décès","De délivrer le permis d'inhumer","De pratiquer l'embaumement"],c:1,art:"Art. 74 CPP",diff:2,expl:"Le médecin légiste pratique un <strong>examen externe du corps</strong> et émet un avis sur la cause du décès. L'autopsie est ordonnée séparément si nécessaire."},
  {id:'cdo07',cat:'CDO',q:"Les pouvoirs de l'OPJ dans le cadre de l'art. 74 CPP sont :",opts:["Identiques à ceux de la flagrance","Des pouvoirs d'investigation propres, sans les pouvoirs coercitifs de la flagrance","Identiques à ceux de la préliminaire","Limités à la prise de photographies"],c:1,art:"Art. 74 CPP",diff:2,expl:"L'art. 74 confère à l'OPJ des <strong>pouvoirs d'investigation propres</strong>, distincts de ceux de la flagrance et de la préliminaire."},
  {id:'cdo08',cat:'CDO',q:"Le procès-verbal de transport sur les lieux (art. 74 CPP) doit mentionner :",opts:["Uniquement l'identité du défunt","L'état et la position du corps, les constatations matérielles et les mesures prises","Seulement la cause du décès","Le nom des témoins exclusivement"],c:1,art:"Art. 74 CPP",diff:2,expl:"Le PV doit décrire l'<strong>état et la position du corps, les constatations matérielles</strong> et toutes les mesures conservatoires prises."},
  {id:'cdo09',cat:'CDO',q:"Si l'enquête art. 74 CPP révèle une cause criminelle, le procureur peut :",opts:["Classer sans suite uniquement","Ouvrir une enquête de flagrance ou requérir l'ouverture d'une information judiciaire","Ordonner l'inhumation immédiate","Saisir le tribunal de police"],c:1,art:"Art. 74 CPP",diff:2,expl:"Si une cause criminelle est révélée, le PR peut <strong>ouvrir une enquête de flagrance ou saisir un juge d'instruction</strong>."},
  {id:'cdo10',cat:'CDO',q:"Les mesures conservatoires sur les lieux de découverte d'un cadavre comprennent :",opts:["L'évacuation du corps uniquement","La protection et le gel de la scène, l'interdiction d'accès aux tiers","L'audition immédiate du défunt","La destruction des indices"],c:1,art:"Art. 74 CPP",diff:1,expl:"Les mesures conservatoires incluent la <strong>protection de la scène, le gel des lieux et l'interdiction d'accès</strong> pour préserver les indices."},

  /* ── CONTROLES (ctrl06–ctrl10) ── */
  {id:'ctrl06',cat:'CONTROLES',q:"Le contrôle d'identité sur réquisitions du procureur (art. 78-2 al. 7 CPP) doit préciser :",opts:["L'identité des personnes visées","Les lieux, la période et les infractions recherchées","Le nombre d'agents mobilisés","Le nom du préfet"],c:1,art:"Art. 78-2 al. 7 CPP",diff:2,expl:"Les réquisitions du PR doivent préciser les <strong>lieux, la période et les infractions recherchées</strong> pour encadrer le contrôle."},
  {id:'ctrl07',cat:'CONTROLES',q:"La palpation de sécurité (art. 78-2-2 CPP) :",opts:["Est une fouille à corps complète","Est un contrôle externe des vêtements pour détecter un objet dangereux","Nécessite une autorisation du JLD","Peut être pratiquée par toute personne"],c:1,art:"Art. 78-2-2 CPP",diff:1,expl:"La palpation de sécurité est un <strong>contrôle externe des vêtements</strong> visant à détecter un objet dangereux, distinct de la fouille à corps."},
  {id:'ctrl08',cat:'CONTROLES',q:"Le contrôle de véhicule dans le cadre de l'art. 78-2-2 CPP peut inclure :",opts:["La fouille approfondie du coffre sans condition","L'inspection visuelle et la fouille du véhicule sur réquisitions du PR","Le démontage du véhicule","La confiscation immédiate"],c:1,art:"Art. 78-2-2 CPP",diff:2,expl:"La fouille du véhicule sur réquisitions du PR permet une <strong>inspection visuelle et fouille</strong> dans le cadre défini par les réquisitions."},
  {id:'ctrl09',cat:'CONTROLES',q:"La distinction entre contrôle d'identité judiciaire et administratif est :",opts:["Inexistante en droit français","Le judiciaire vise à rechercher des auteurs d'infractions, l'administratif à prévenir les troubles à l'ordre public","Le judiciaire est réservé aux gendarmes","L'administratif est réservé aux douaniers"],c:1,art:"Art. 78-2 CPP",diff:2,expl:"Le contrôle <strong>judiciaire recherche des auteurs d'infractions</strong> ; le contrôle <strong>administratif vise la prévention des troubles</strong> à l'ordre public."},
  {id:'ctrl10',cat:'CONTROLES',q:"En cas de vérification d'identité (art. 78-3 CPP), la personne retenue peut :",opts:["Être auditionnée sur les faits","Uniquement être soumise aux opérations de vérification d'identité","Être perquisitionnée à domicile","Être confrontée à des témoins"],c:1,art:"Art. 78-3 CPP",diff:2,expl:"Pendant la rétention de 4h, la personne ne peut être soumise qu'aux <strong>opérations de vérification d'identité</strong> (empreintes, photographies)."},

  /* ── MESURES_COERC (mc06–mc10) ── */
  {id:'mc06',cat:'MESURES_COERC',q:"Le contrôle judiciaire (art. 138 CPP) peut être ordonné par :",opts:["L'OPJ","Le juge d'instruction ou le JLD","Le procureur de la République seul","Le préfet"],c:1,art:"Art. 138 CPP",diff:1,expl:"Le contrôle judiciaire est ordonné par le <strong>juge d'instruction ou le JLD</strong>."},
  {id:'mc07',cat:'MESURES_COERC',q:"Le mandat de dépôt (art. 122 CPP) ordonne :",opts:["La comparution devant le JI","La remise de la personne au chef de l'établissement pénitentiaire","La libération sous conditions","Le placement en ARSE"],c:1,art:"Art. 122 CPP",diff:2,expl:"Le mandat de dépôt ordonne la <strong>remise de la personne mise en examen ou condamnée au chef de l'établissement pénitentiaire</strong>."},
  {id:'mc08',cat:'MESURES_COERC',q:"L'ARSE (art. 142-5 CPP) impose le port d'un bracelet électronique et :",opts:["La garde à vue","L'assignation au domicile avec plages horaires de sortie autorisées","La détention provisoire","L'incarcération immédiate"],c:1,art:"Art. 142-5 CPP",diff:2,expl:"L'ARSE combine le <strong>bracelet électronique et l'assignation à domicile</strong> avec des plages horaires de sortie définies par le juge."},
  {id:'mc09',cat:'MESURES_COERC',q:"La mise en examen (art. 80-1 CPP) ne peut intervenir qu'au stade de :",opts:["L'enquête préliminaire","L'enquête de flagrance","L'information judiciaire","Le jugement"],c:2,art:"Art. 80-1 CPP",diff:1,expl:"La mise en examen est un acte propre à l'<strong>information judiciaire</strong>, prononcé par le juge d'instruction."},
  {id:'mc10',cat:'MESURES_COERC',q:"Le placement sous bracelet électronique dans le cadre de l'ARSE est décidé par :",opts:["Le procureur de la République","Le JLD sur saisine du juge d'instruction","L'administration pénitentiaire","Le préfet"],c:1,art:"Art. 142-5 CPP",diff:2,expl:"Le placement sous ARSE est décidé par le <strong>JLD</strong>, saisi par ordonnance motivée du juge d'instruction."},

  /* ── ACTION_PUB (apub07–apub10) ── */
  {id:'apub07',cat:'ACTION_PUB',q:"Le principe de l'opportunité des poursuites (art. 40-1 CPP) signifie que :",opts:["Le PR est obligé de poursuivre toute infraction","Le PR choisit librement de poursuivre, de mettre en œuvre une alternative ou de classer","Le JI décide seul des poursuites","La victime déclenche automatiquement l'action publique"],c:1,art:"Art. 40-1 CPP",diff:1,expl:"L'opportunité des poursuites donne au PR le <strong>choix entre poursuivre, recourir à une alternative ou classer sans suite</strong>."},
  {id:'apub08',cat:'ACTION_PUB',q:"La constitution de partie civile devant le juge d'instruction (art. 85 CPP) :",opts:["Remplace l'action publique","Met en mouvement l'action publique si le PR ne l'a pas fait","Éteint l'action publique","N'est possible qu'après jugement"],c:1,art:"Art. 85 CPP",diff:2,expl:"La plainte avec constitution de partie civile <strong>met en mouvement l'action publique</strong> si le PR n'a pas agi (après un délai de 3 mois)."},
  {id:'apub09',cat:'ACTION_PUB',q:"La citation directe permet à la victime de :",opts:["Saisir le juge d'instruction","Citer directement l'auteur devant le tribunal correctionnel ou de police","Déposer une main courante","Demander une médiation"],c:1,art:"Art. 388 CPP",diff:2,expl:"La citation directe permet à la victime de <strong>saisir directement le tribunal correctionnel ou de police</strong> sans passer par le parquet."},
  {id:'apub10',cat:'ACTION_PUB',q:"Le procureur de la République est le chef :",opts:["De la police administrative","Du parquet près le tribunal judiciaire","De la chambre de l'instruction","Du tribunal correctionnel"],c:1,art:"Art. 39-3 CPP",diff:1,expl:"Le PR est le <strong>chef du parquet près le tribunal judiciaire</strong>. Il dirige l'action publique et contrôle la police judiciaire."},

  /* ── FICHIERS (fich07–fich10) ── */
  {id:'fich07',cat:'FICHIERS',q:"Le FAED (Fichier Automatisé des Empreintes Digitales) est régi par :",opts:["Art. 706-54 CPP","Le décret n° 87-249 du 8 avril 1987","Art. 78-2 CPP","Le Code civil"],c:1,art:"Décret 87-249",diff:2,expl:"Le FAED est régi par le <strong>décret n° 87-249</strong>. Il contient les empreintes digitales et palmaires des personnes mises en cause et condamnées."},
  {id:'fich08',cat:'FICHIERS',q:"Le N-SIS II (volet national du Système d'Information Schengen) permet :",opts:["De géolocaliser en temps réel","De signaler des personnes et des objets recherchés dans l'espace Schengen","De stocker les profils ADN","D'intercepter les communications"],c:1,art:"Règlement UE 1987/2006",diff:2,expl:"Le N-SIS II permet de <strong>signaler des personnes et objets recherchés</strong> dans l'espace Schengen (mandats, disparitions, véhicules volés)."},
  {id:'fich09',cat:'FICHIERS',q:"Le droit d'accès indirect aux fichiers de police (TAJ, FPR) s'exerce auprès de :",opts:["L'OPJ","La CNIL","Le procureur de la République","Le maire"],c:1,art:"Loi Informatique et Libertés",diff:2,expl:"Le droit d'accès indirect aux fichiers de police s'exerce par l'intermédiaire de la <strong>CNIL</strong> qui vérifie la légalité des données."},
  {id:'fich10',cat:'FICHIERS',q:"L'effacement des données du FNAEG peut être demandé par :",opts:["N'importe qui sans condition","Le mis en cause acquitté ou relaxé, auprès du procureur de la République","Le préfet uniquement","La CNIL d'office"],c:1,art:"Art. 706-54-1 CPP",diff:3,expl:"La personne acquittée ou relaxée peut demander l'<strong>effacement de ses données du FNAEG auprès du PR</strong>."},

  /* ── ENQUETES_SPEC (es07–es10) ── */
  {id:'es07',cat:'ENQUETES_SPEC',q:"L'infiltration (art. 706-81 CPP) est autorisée par :",opts:["L'OPJ","Le procureur de la République ou le juge d'instruction selon le cadre de l'enquête","Le préfet","Le JLD exclusivement"],c:1,art:"Art. 706-81 CPP",diff:2,expl:"L'infiltration est autorisée par le <strong>PR (en enquête) ou le JI (en instruction)</strong> pour une durée de 4 mois renouvelable."},
  {id:'es08',cat:'ENQUETES_SPEC',q:"Les écoutes téléphoniques en enquête préliminaire (art. 706-95 CPP) sont autorisées par :",opts:["Le procureur de la République seul","Le JLD sur requête du PR","L'OPJ avec accord du PR","Le juge d'instruction"],c:1,art:"Art. 706-95 CPP",diff:2,expl:"En préliminaire, les interceptions sont autorisées par le <strong>JLD sur requête du PR</strong>, pour les infractions de criminalité organisée."},
  {id:'es09',cat:'ENQUETES_SPEC',q:"La sonorisation et la captation d'images dans un lieu privé (art. 706-96 CPP) sont réservées :",opts:["À toute enquête","Aux infractions de criminalité organisée, sur autorisation du JI ou du JLD","Aux contraventions","Aux contrôles d'identité"],c:1,art:"Art. 706-96 CPP",diff:3,expl:"La sonorisation et captation d'images dans un lieu privé sont réservées à la <strong>criminalité organisée</strong> et autorisées par le JI ou le JLD."},
  {id:'es10',cat:'ENQUETES_SPEC',q:"L'enquête sous pseudonyme (art. 230-46 CPP) permet aux enquêteurs de :",opts:["Se faire passer pour un magistrat","Participer à des échanges en ligne sous une identité d'emprunt","Effectuer des écoutes téléphoniques","Perquisitionner sans mandat"],c:1,art:"Art. 230-46 CPP",diff:2,expl:"L'enquête sous pseudonyme permet aux OPJ de <strong>participer à des échanges électroniques sous une identité d'emprunt</strong> pour constater certaines infractions."},

  /* ── MANDATS (mand08–mand10) ── */
  {id:'mand08',cat:'MANDATS',q:"Quel magistrat est compétent pour délivrer un mandat d'arrêt ?",opts:["Le procureur de la République","Le juge d'instruction","Le juge des libertés et de la détention","Le président du tribunal"],c:1,art:"Art. 122 CPP",diff:2,expl:"Seul le juge d'instruction peut délivrer un mandat d'arrêt (art. 122 CPP). Le JLD intervient pour la détention provisoire, pas pour les mandats."},
  {id:'mand09',cat:'MANDATS',q:"Quelle est la durée maximale de rétention sous mandat de recherche avant présentation au magistrat ?",opts:["24 heures","48 heures","72 heures","Pas de délai"],c:0,art:"Art. 134 CPP",diff:2,expl:"La personne découverte doit être présentée dans les 24 heures au procureur du lieu de l'arrestation (art. 134 CPP)."},
  {id:'mand10',cat:'MANDATS',q:"Le mandat d'amener permet-il l'usage de la force publique ?",opts:["Non, jamais","Oui, il autorise le recours à la force publique pour conduire la personne","Uniquement avec l'accord du JLD","Seulement pour les crimes"],c:1,art:"Art. 122 CPP",diff:1,expl:"Le mandat d'amener est l'ordre donné à la force publique de conduire immédiatement la personne devant le magistrat (art. 122 CPP)."},

  /* ── NULLITES (n07–n09) ── */
  {id:'n07',cat:'NULLITES',q:"Qu'est-ce qu'une nullité textuelle ?",opts:["Une nullité prononcée même sans grief","Une nullité qui nécessite un grief","Une nullité corrigeable","Une nullité partielle"],c:0,art:"Art. 171 CPP",diff:1,expl:"La nullité textuelle est prévue expressément par un texte de loi et n'exige pas la démonstration d'un grief (art. 171 CPP)."},
  {id:'n08',cat:'NULLITES',q:"Quel est l'effet de la purge des nullités en matière de mise en examen ?",opts:["Les nullités antérieures ne peuvent plus être invoquées","Les nullités sont suspendues","Le juge peut les soulever d'office indéfiniment","La prescription est interrompue"],c:0,art:"Art. 175 CPP",diff:3,expl:"L'ordonnance de règlement purge les nullités : les parties qui ne les ont pas soulevées dans le délai de l'art. 175 CPP ne peuvent plus le faire."},
  {id:'n09',cat:'NULLITES',q:"Une nullité substantielle requiert la démonstration de quel élément ?",opts:["Un grief (atteinte aux intérêts de la partie)","La mauvaise foi de l'OPJ","L'intentionnalité de la violation","Un préjudice financier"],c:0,art:"Art. 802 CPP",diff:2,expl:"La nullité substantielle (d'ordre général, art. 171) exige la preuve d'un grief, c'est-à-dire une atteinte aux intérêts de la partie qui l'invoque (art. 802 CPP)."},

  /* ── COMMISSION (cr09–cr10) ── */
  {id:'cr09',cat:'COMMISSION',q:"Qui délivre la commission rogatoire ?",opts:["Le procureur de la République","Le juge d'instruction","Le préfet","Le JLD"],c:1,art:"Art. 151 CPP",diff:1,expl:"La commission rogatoire est délivrée par le juge d'instruction aux OPJ pour accomplir des actes d'information en son nom (art. 151 CPP)."},
  {id:'cr10',cat:'COMMISSION',q:"L'OPJ agissant sur commission rogatoire peut-il placer une personne en garde à vue ?",opts:["Oui, avec les mêmes droits que la GAV de droit commun","Non, jamais","Seulement avec autorisation préalable du JI","Oui, mais limitée à 12 heures"],c:0,art:"Art. 154 CPP",diff:2,expl:"L'OPJ agissant sur CR peut placer en GAV avec notification des droits identiques à la GAV de droit commun. Il doit en informer le JI dès le début (art. 154 CPP)."},

  /* ── LIBERTES (lib09–lib10) ── */
  {id:'lib09',cat:'LIBERTES',q:"Quel article de la CEDH garantit le droit à un procès équitable ?",opts:["Article 5","Article 6","Article 8","Article 3"],c:1,art:"Art. 6 CEDH",diff:1,expl:"L'article 6 de la Convention européenne des droits de l'homme garantit le droit à un procès équitable, incluant le droit à un tribunal indépendant et impartial."},
  {id:'lib10',cat:'LIBERTES',q:"Le principe de présomption d'innocence est garanti par quel article du Code de procédure pénale ?",opts:["Article préliminaire","Article 1","Article 40","Article 63"],c:0,art:"Art. préliminaire CPP",diff:2,expl:"L'article préliminaire du CPP consacre la présomption d'innocence : toute personne suspectée ou poursuivie est présumée innocente tant que sa culpabilité n'a pas été établie."},
];

